      "content": "{\n  \"name\": \"dsh-ark-coding-provider\",\n  \"version\": \"0.5.0\",\n  \"description\": \"火山方舟 Coding Plan（Volcengine Ark Coding Plan）的 DeepSeek Harness 提供商插件：注册 ark-coding 路由、12 个模型目录、内置 arkcli 取官方模型目录与真实套餐额度、多账户（CLI SSO 登录 / API Key）、设置页登录向导与侧边栏用量卡片（点击展开登录情况与三档额度）。\",\n  \"icon\": \"./icon.svg\",\n  \"type\": \"module\",\n  \"main\": \"./index.js\",\n  \"exports\": {\n    \".\": \"./index.js\",\n    \"./client\": \"./client.js\",\n    \"./models\": \"./models.js\",\n    \"./accounts\": \"./accounts.js\",\n    \"./usage\": \"./usage.js\",\n    \"./arkcli\": \"./arkcli.js\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"client.js\",\n    \"models.js\",\n    \"accounts.js\",\n    \"usage.js\",\n    \"arkcli.js\",\n    \"icon.svg\",\n    \"locale\",\n    \"tests\",\n    \"cordis.patch.yml\",\n    \"README.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-api-remotes\"\n      ]\n    },\n    \"compatibility\": {\n      \"dsh\": \"0.2.0-rc.2\",\n      \"dshReleases\": {\n        \"0.2.0-rc.2\": \"compatible\"\n      }\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-credentials\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-launch-environment\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/schemastery\": \"~3.18.4\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"volcengine\",\n    \"ark\",\n    \"coding-plan\",\n    \"火山方舟\",\n    \"doubao\",\n    \"llm\",\n    \"provider\",\n    \"plugin\"\n  ],\n  \"scripts\": {\n    \"test\": \"node tests/run.mjs\",\n    \"pack:local\": \"npm pack\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Akiyuki1130/dsh-ark-coding-provider.git\"\n  }\n}\n"
