      "path": "index.js",
      "content": "/**\n * dsh-ark-coding-provider — 火山方舟（Volcengine Ark）Coding Plan 的 DeepSeek\n * Harness LLM 提供商插件（非官方社区集成）。\n *\n * 线路协议是 OpenAI 兼容的 `POST {base}/chat/completions`（SSE 流式）：\n * `https://ark.cn-beijing.volces.com/api/coding/v3`。因此适配器只做三件事：\n * 把 DSH 的规范化消息翻译成 OpenAI 形状、解析 SSE 成 StreamChunk、把失败归类成\n * DSH 的稳定失败码。没有反向工程的私有协议。\n *\n * 注册一个提供商路由 `ark-coding`，并在 configurable-provider 目录里登记，\n * 于是设置页会多出一张「火山方舟 Coding Plan」卡片、模型选择器里会列出这 12 个模型。\n * 连接事实（密钥、端点、超时）每次请求都从实时 Config 与凭据 seam 重新解析，\n * 所以改完密钥或端点下一个请求就生效，不需要重启。\n *\n * ```yaml\n * - id: llm-ark-coding\n *   name: \"dsh-ark-coding-provider\"\n *   config:\n *     apiKeyEnv: ARK_CODING_API_KEY\n * ```\n *\n * @module dsh-ark-coding-provider\n */\n\nimport { resolve as resolvePath, sep as pathSep } from 'node:path'\nimport z from '@deepseek-ai/schemastery'\nimport {\n  EMPTY_RESPONSE_CODE,\n  INVALID_CREDENTIAL_CODE,\n  LlmAdapter,\n  LlmError,\n  assertUsableApiKey,\n  attributionHeaders,\n  isContextWindowExceededError,\n  isQuotaExceededError,\n  normalizeApiKey,\n  offloadedImageText,\n  projectOffloadedImages,\n  requiredImageOffload,\n  resolveRetryPolicy,\n} from '@deepseek-ai/dsh-llm'\nimport { credentialRef, isCredentialRefName } from '@deepseek-ai/dsh-credentials'\nimport { launchEnvironmentOf } from '@deepseek-ai/dsh-launch-environment'\nimport { TypertRemoteService } from '@deepseek-ai/dsh-typert-protocol'\nimport { EFFORT_WIRE, MODELS, annotateModels, modelById } from './models.js'\nimport {\n  AccountMarks,\n  TYPE_API_KEY,\n  TYPE_CLI,\n  cooldownFor,\n  describeAccounts,\n  orderAccounts,\n  retryAfterMsOf,\n  rotationReasonFor,\n  sidebarQuotaState,\n} from './accounts.js'\nimport { VOLC_DEFAULT_REGION, fetchCodingPlanUsage } from './usage.js'\nimport { ArkCli, ArkCliLogin, accountHomeDir, arkcliStateRoot, readCredentialExpiry } from './arkcli.js'\n\n/** 本插件拥有的提供商路由 id。 */\nexport const PROVIDER = 'ark-coding'\n/** 本插件的设置命名空间（也是 profile 里的条目 id）。 */\nexport const NS = 'llm-ark-coding'\nexport const name = 'llm-ark-coding'\nexport const inject = ['llm']\n\n/** Coding Plan 的 OpenAI 兼容端点。 */\nexport const DEFAULT_API_BASE = 'https://ark.cn-beijing.volces.com/api/coding/v3'\nexport const DEFAULT_API_KEY_ENV = 'ARK_CODING_API_KEY'\nexport const DISPLAY_NAME = '火山方舟 Coding Plan'\n\n/** 未配置时单次请求的 max_tokens 上限；会被逐模型输出上限夹住。 */\nexport const DEFAULT_MAX_OUTPUT_TOKENS = 65536\n/** 首字节超时与流空闲超时。Coding Plan 会出现很长的思考，默认给足 5 分钟。 */\nexport const DEFAULT_REQUEST_TIMEOUT_MS = 300_000\nexport const DEFAULT_STREAM_IDLE_TIMEOUT_MS = 300_000\n/** 单次请求内联图片（base64 后）的字节上限；超出即要求上层卸载最旧的图片。 */\nexport const DEFAULT_MAX_REQUEST_IMAGE_BYTES = 20 * 1024 * 1024\n/** 请求版图片的长边上限与编码字节上限。 */\nconst REQUEST_IMAGE_MAX_LONG_EDGE = 1568\nconst REQUEST_IMAGE_MAX_ENCODED_BYTES = 1024 * 1024\n/**\n * `Retry-After` 的采用上界（1 小时）。\n *\n * 服务端说什么就等什么是对的，但\"说什么\"可能是坏值：实测畸形值会把账户冷却到\n * ~1e23 ms，等于本进程内永久不可用。1 小时足够长（正常值都是秒级）又不会失控。\n */\nconst RETRY_AFTER_MAX_MS = 60 * 60_000\n/**\n * 单条 SSE 行的字节上限。\n *\n * 不设上限时，一条巨型 `data:` 行会在内存里放大十几倍：实测 8/16/32/64 MB 输入\n * 分别让 RSS 涨 132/375/476/1082 MB、耗时 0.8/2.8/10.4/44 秒 —— 上游、被劫持的\n * 网关或坏代理塞一条就能把宿主拖垮，而 `apiBase` 是可配置的。正常帧远小于 1 MB。\n */\nconst MAX_SSE_LINE_BYTES = 8 * 1024 * 1024\n/** setTimeout 的可靠上界。 */\nconst MAX_TIMER_DELAY_MS = 2_147_483_647\n\n// ---------------------------------------------------------------------------\n// Config\n// ---------------------------------------------------------------------------\n\n/** 标一个 schema 字段为易变（volatile）——设置页只能写被标记的节点。 */\nfunction markVolatile(schema) {\n  return schema.volatile()\n}\n\n/** 逐个标记顶层字段为易变，`apiKey` 字面量除外（没有页面会写它）。 */\nfunction markVolatileFields(fields, skip = []) {\n  return Object.fromEntries(\n    Object.entries(fields).map(([key, schema]) => [key, skip.includes(key) ? schema : markVolatile(schema)]),\n  )\n}\n\n/**\n * 插件配置。被标记为易变的字段由设置页改写，加载器就地提交并热重载，\n * 因此 `current()` 每次读取都要拆开 volatile 引用。\n */\nexport const Config = z.object(markVolatileFields({\n  apiKeyEnv: z.string().role('credential-ref').default(DEFAULT_API_KEY_ENV),\n  // 字面量密钥：只有组合配置会写它，因此保持非易变，并且必须带 secret 角色，\n  // 否则它会随设置描述一起回到浏览器。\n  apiKey: z.string().role('secret'),\n  apiBase: z.string().default(DEFAULT_API_BASE),\n  requestTimeoutMs: z.number().min(1).max(MAX_TIMER_DELAY_MS).default(DEFAULT_REQUEST_TIMEOUT_MS),\n  streamIdleTimeoutMs: z.number().min(1).max(MAX_TIMER_DELAY_MS).default(DEFAULT_STREAM_IDLE_TIMEOUT_MS),\n  defaultMaxTokens: z.number().min(1).default(DEFAULT_MAX_OUTPUT_TOKENS),\n  /** 允许出现在模型选择器里的模型 id；为空 = 全部可见。 */\n  visibleModels: z.array(z.string()),\n  /** 逐模型开关，覆盖 `visibleModels` 的批量结果。 */\n  modelVisibility: z.dict(z.boolean()),\n  /** 逐模型覆盖上下文长度（应对上游容量变化，不必等插件更新）。 */\n  contextWindowOverrides: z.dict(z.number().min(1024)),\n  /**\n   * 账户池。**账户主要写在这里**（设置页保存后全部落在这）。\n   *\n   * 另外有一条**兜底**：`accounts` 为空时，顶层 `apiKeyEnv` / `apiKey` 会被当作一个\n   * id 为 `default` 的 API Key 账户（见 `describeAccounts` 的第二个参数）。这不是\n   * \"隐式魔法\"，而是官方 Models 页的密钥编辑器唯一能落地的地方 —— 它写的 ref 是从\n   * provider 名推出来的 `ARK_CODING_API_KEY`，插件管不着；不读它就会出现\"官方卡片\n   * 显示已配置、聊天却说没有可用账户\"。把 `apiKeyEnv` 显式设成空串即关闭这条兜底。\n   *\n   * 每个账户：\n   * - `id`：稳定标识，CLI 账户的 HOME 目录名由它派生，所以不要随便改。\n   * - `label`：显示名，可留空（留空则按类型显示「API Key 账户 N」）。\n   * - `type`：`apikey`（手填 key）或 `cli`（arkcli SSO 登录）。\n   * - `apiKeyEnv` / `apiKey`：只有 apikey 用得上。\n   * - `home`：只有 cli 用得上；留空表示用 `<DSH_HOME>/ark-coding/accounts/<id>`。\n   *   **显式值必须位于 `<DSH_HOME>/ark-coding` 之下**：它会成为 root 子进程的 HOME，\n   *   允许任意路径等于让一次配置写入就能让 root 往任意目录写文件（见 `homeForAccount`）。\n   */\n  accounts: z.array(z.object({\n    id: z.string(),\n    label: z.string(),\n    type: z.string().default(TYPE_API_KEY),\n    apiKeyEnv: z.string().role('credential-ref'),\n    /** 只在组合配置里写的字面量密钥；带 secret 角色，不会被设置描述回传。 */\n    apiKey: z.string().role('secret'),\n    home: z.string(),\n  })),\n  /** 配置里偏好的账户 id（`default` / `account-2` / …）；空 = 按顺序。 */\n  activeAccount: z.string(),\n  /**\n   * 左下角用量卡片：`auto`（默认）/ `on` / `off`。\n   *\n   * `auto` 的判据是**有没有能取到套餐额度的绑定** —— 已登录的 CLI（SSO）账户，\n   * 或一对填全了的 AK/SK。两者都没有时卡片根本不渲染（一张永远只写着\"未配置\"\n   * 的卡片比没有卡片更烦人）；绑上之后它自动出现，不需要谁再去手动打开一次。\n   *\n   * 以前这里是 `z.boolean().default(true)`：schema 默认值会把「用户没配」填成\n   * `true`，「自动」这一档就永远生效不了，所以改成显式三态字符串。\n   */\n  sidebarQuota: z.union(['auto', 'on', 'off']).default('auto'),\n  /**\n   * 套餐额度的**备选**来源：一对 AK/SK。\n   *\n   * 主路径已经是 arkcli（SSO 登录的账户自带 `usage plan`），这一对只在\n   * \"有 AK/SK、但不想装 arkcli / 不想 SSO 登录\"时用得上：本插件自己按\n   * Volcengine V4 签名调 `GetCodingPlanUsage`。注意 1.0.16 起 arkcli 已经\n   * 关掉了 AK/SK 登录通道，所以这条路的凭据只能由用户手填。\n   *\n   * 只有 AccessKey ID 放在这里（它不是秘密），Secret 走凭据引用 `secretAccessKeyEnv`。\n   */\n  accessKeyId: z.string(),\n  secretAccessKeyEnv: z.string().role('credential-ref').default('ARK_ACCESS_KEY_SECRET'),\n  region: z.string().default(VOLC_DEFAULT_REGION),\n  /** 显式指定 arkcli 可执行文件；留空则按「插件自装目录 → PATH」的顺序找。 */\n  arkcliPath: z.string(),\n  /** 官方模型目录的刷新间隔（秒）。目录是控制面数据，没必要每次轮询都拉。 */\n  catalogRefreshSeconds: z.number().min(60).max(86_400).default(3600),\n  /** 用量刷新间隔（秒）；卡片打开时按这个节奏轮询。 */\n  usageRefreshSeconds: z.number().min(10).max(3600).default(60),\n}, ['apiKey']))\n\n/** 一个已解析的 volatile 引用。 */\nfunction isVolatileRef(value) {\n  return typeof value === 'object'\n    && value !== null\n    && !Array.isArray(value)\n    && Object.isFrozen(value)\n    && typeof value.get === 'function'\n}\n\n/** 把配置里的每个顶层 volatile 引用读成普通值（每次调用都新鲜）。 */\nfunction unwrapVolatileConfig(config) {\n  if (typeof config !== 'object' || config === null) return config\n  const plain = {}\n  for (const [key, value] of Object.entries(config)) {\n    plain[key] = isVolatileRef(value) ? value.get() : value\n  }\n  return plain\n}\n\n/** 一个请求要用的完整连接事实。 */\nfunction resolveConnection(config) {\n  const rawBase = typeof config.apiBase === 'string' && config.apiBase.trim() !== ''\n    ? config.apiBase.trim()\n    : DEFAULT_API_BASE\n  return {\n    apiBase: rawBase.replace(/\\/+$/, ''),\n    // 顶层 `apiKeyEnv` 只在一个用途上被读到：`accounts` 为空时作为兜底账户的凭据引用\n    // （见 `describeAccounts` 的第二参数）。官方 Models 页的密钥编辑器写的就是这个 ref。\n    //\n    // 以前这里对任意字符串直接调 `credentialRef()`，而它是**会抛的**：空串、或\n    // `MY-KEY` 这种带 `-` 的名字（看着完全合法，但不符合凭据 ref 文法）都会让\n    // `connection()` 整体抛错 —— 于是每一个请求、每一次 report() 都失败，设置页卡片\n    // 也起不来，而那个字段当时根本没人读。现在先校验，非法/空就当\"没有兜底\"。\n    fallbackRef: isValidRefName(config.apiKeyEnv) ? config.apiKeyEnv.trim() : undefined,\n    literalApiKey: typeof config.apiKey === 'string' && config.apiKey.trim() !== '' ? config.apiKey.trim() : undefined,\n    requestTimeoutMs: positive(config.requestTimeoutMs, DEFAULT_REQUEST_TIMEOUT_MS),\n    streamIdleTimeoutMs: positive(config.streamIdleTimeoutMs, DEFAULT_STREAM_IDLE_TIMEOUT_MS),\n    defaultMaxTokens: positive(config.defaultMaxTokens, DEFAULT_MAX_OUTPUT_TOKENS),\n    visibleModels: Array.isArray(config.visibleModels) ? config.visibleModels.filter((id) => typeof id === 'string') : [],\n    modelVisibility: isPlainObject(config.modelVisibility) ? config.modelVisibility : {},\n    contextWindowOverrides: isPlainObject(config.contextWindowOverrides) ? config.contextWindowOverrides : {},\n    /** 账号定义（尚未解析 key）。 */\n    accounts: describeAccounts(config, isValidRefName(config.apiKeyEnv) ? config.apiKeyEnv.trim() : undefined),\n    activeAccount: typeof config.activeAccount === 'string' ? config.activeAccount : '',\n    sidebarQuota: config.sidebarQuota === 'on' || config.sidebarQuota === 'off' ? config.sidebarQuota : 'auto',\n    accessKeyId: typeof config.accessKeyId === 'string' ? config.accessKeyId.trim() : '',\n    secretAccessKeyEnv: typeof config.secretAccessKeyEnv === 'string' && config.secretAccessKeyEnv !== ''\n      ? config.secretAccessKeyEnv\n      : 'ARK_ACCESS_KEY_SECRET',\n    region: typeof config.region === 'string' && config.region.trim() !== '' ? config.region.trim() : VOLC_DEFAULT_REGION,\n    arkcliPath: typeof config.arkcliPath === 'string' ? config.arkcliPath.trim() : '',\n    catalogRefreshSeconds: positive(config.catalogRefreshSeconds, 3600),\n    usageRefreshSeconds: positive(config.usageRefreshSeconds, 60),\n  }\n}\n\nfunction positive(value, fallback) {\n  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? Math.trunc(value) : fallback\n}\n\n/**\n * 凭据引用名是否合法（文法 `^[A-Za-z_][A-Za-z0-9_]*$`）。\n *\n * `credentialRef()` 对不合法的名字**会直接抛**，而那个抛错发生在 `resolveRef` 里就会\n * 让整个账户被静默剔除（外层 catch 把它当成\"这个账户没配 key\"），用户只看到\n * \"账户都还没有可用的 API key\"，完全猜不到是自己 ref 名里有个 `-`。用户手填的 ref\n * 什么形状都可能有，所以先判断：不合法就跳过凭据服务，让启动环境（export/.env）兜底。\n */\nfunction isValidRefName(value) {\n  if (typeof value !== 'string') return false\n  const trimmed = value.trim()\n  if (trimmed === '') return false\n  try { return isCredentialRefName(trimmed) === true } catch { return false }\n}\n\nfunction isPlainObject(value) {\n  return typeof value === 'object' && value !== null && !Array.isArray(value)\n}\n\n/**\n * 摘掉属性值为 `undefined` 的键。\n *\n * **为什么需要它**：DSH 在把每一块流式内容落地之前会做一次\"无损 JSON\"校验\n * （`snapshotJsonValue`），而 `{ foo: undefined }` 这种**显式 undefined 属性**在 JSON\n * 里根本无法表示，于是被判成\"不可无损序列化\"，直接抛\n * `Assistant stream chunk must be losslessly JSON-serializable` —— 后果是\n * **整轮对话在最后一块上失败**。用户看到的现象就是\"字都打出来了，然后突然没了\"。\n *\n * 修 `{ finish, replayState: undefined }` 这一处只是治标：JS 里写 `foo: maybeUndefined`\n * 太顺手，下次随手加一个可选字段又会重演。所以放在流式内容的唯一出口兜一层 ——\n * JSON 语义上 `{ foo: undefined }` 与 `{}` 完全等价，摘掉是忠实的，不是掩盖。\n */\nfunction withoutUndefined(chunk) {\n  if (typeof chunk !== 'object' || chunk === null) return chunk\n  for (const key of Object.keys(chunk)) {\n    if (chunk[key] === undefined) delete chunk[key]\n  }\n  return chunk\n}\n\n// ---------------------------------------------------------------------------\n// 目录投影\n// ---------------------------------------------------------------------------\n\n/** 一个模型在当前配置下的上下文长度（配置覆盖优先）。 */\nfunction contextWindowOf(model, connection) {\n  const override = connection.contextWindowOverrides[model.id]\n  return positive(override, model.contextWindow)\n}\n\n/** 一个模型是否出现在模型选择器里。 */\nfunction modelIsVisible(id, connection) {\n  const explicit = connection.modelVisibility[id]\n  if (typeof explicit === 'boolean') return explicit\n  if (connection.visibleModels.length === 0) return true\n  return connection.visibleModels.includes(id)\n}\n\n/** DSH 只认识 text/image 两种模态；目录已经按实测值写好。 */\nfunction modalitiesOf(model) {\n  return model.input.filter((m) => m === 'text' || m === 'image')\n}\n\n/** 目录项 → `LlmModelInfo`。 */\nfunction toModelInfo(model, connection) {\n  return {\n    provider: PROVIDER,\n    id: model.id,\n    name: model.name,\n    // 这个 description 会出现在 harness **共享的**模型选择器里，而那里没有插件侧的语言\n    // 席位 —— 写中文的话，英文界面下就只有这一行是中文。所以用语言无关的短形式。\n    description: `${model.family} · ${Math.round(contextWindowOf(model, connection) / 1024)}K ctx`,\n    inputModalities: modalitiesOf(model),\n  }\n}\n\n/** 目录项 → `LlmResolvedModelInfo`（含上下文、输出上限、思考档位）。 */\nfunction toResolvedModelInfo(model, connection) {\n  const maxOutput = model.maxOutput\n  return {\n    ...toModelInfo(model, connection),\n    context: { contextWindow: contextWindowOf(model, connection) },\n    defaultMaxTokens: Math.min(connection.defaultMaxTokens, maxOutput),\n    reasoning: {\n      efforts: model.efforts.map((effort) => ({ id: effort.id, name: effort.name })),\n      defaultEffort: model.defaultEffort,\n    },\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 消息翻译（DSH → OpenAI 兼容线路）\n// ---------------------------------------------------------------------------\n\n/** 拼一个 content 数组里的文本。 */\nfunction blockText(blocks) {\n  return blocks\n    .filter((block) => block.type === 'text')\n    .map((block) => block.text)\n    .join('')\n}\n\n/** 判断一条消息的内容里有没有图片块。 */\nfunction hasImage(blocks) {\n  return blocks.some((block) => block.type === 'image')\n}\n\n/** 把一张请求版图片编码成 data URL。 */\nfunction dataUrl(mediaType, bytes) {\n  return `data:${mediaType};base64,${Buffer.from(bytes).toString('base64')}`\n}\n\n/** 计算请求版图片的长边投影（绝不放大，也绝不产生 0 尺寸）。 */\nfunction projectImageSize(width, height, longEdge) {\n  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) {\n    return { width: Math.max(1, Math.round(width) || 1), height: Math.max(1, Math.round(height) || 1) }\n  }\n  if (longEdge >= Math.max(width, height)) return { width, height }\n  return width >= height\n    ? { width: longEdge, height: Math.max(1, Math.round((longEdge * height) / width)) }\n    : { width: Math.max(1, Math.round((longEdge * width) / height)), height: longEdge }\n}\n\n// ---------------------------------------------------------------------------\n// SSE 解析\n// ---------------------------------------------------------------------------\n\n/** 把一次 HTTP 失败归类成 DSH 的稳定失败码。 */\nfunction classifyHttpFailure(status, bodyText, requestId) {\n  const detail = bodyText ?? ''\n  if (status === 401 || status === 403) return { code: 'AUTH', message: `火山方舟鉴权失败（HTTP ${status}）` }\n  if (status === 429) return { code: 'RATE_LIMIT', message: '火山方舟限流（HTTP 429）' }\n  if (status >= 500) return { code: 'SERVER', message: `火山方舟服务端错误（HTTP ${status}）` }\n  if (isContextWindowExceededError(detail)) {\n    return { code: 'CONTEXT_WINDOW_EXCEEDED', message: '请求超出该模型的上下文窗口' }\n  }\n  if (isQuotaExceededError(detail)) return { code: 'QUOTA', message: 'Coding Plan 额度已用尽' }\n  return { code: 'PROVIDER_ERROR', message: `火山方舟拒绝了请求（HTTP ${status}）${requestId === undefined ? '' : ` · ${requestId}`}` }\n}\n\n/** 从响应体里取错误详情，尽力而为。 */\nfunction errorDetail(bodyText) {\n  try {\n    const parsed = JSON.parse(bodyText)\n    const error = parsed?.error\n    if (isPlainObject(error)) {\n      return [error.code, error.type, error.message].filter((part) => typeof part === 'string' && part !== '').join(' ')\n    }\n  } catch {\n    // 非 JSON 的错误体：原样使用截断文本。\n  }\n  return typeof bodyText === 'string' ? bodyText.slice(0, 400) : ''\n}\n\n/** 从错误详情里取 Ark 的 request id。 */\nfunction requestIdOf(bodyText) {\n  const match = /Request id:\\s*([0-9a-zA-Z]+)/.exec(bodyText ?? '')\n  return match?.[1]\n}\n\n/**\n * 读 `Retry-After`（秒或 HTTP 日期）。\n *\n * 方舟在被限流时会带上这个头，冷却时长应当听服务端的 —— 猜一个值只会\n * 要么撞得太早、要么白等太久。\n */\nfunction parseRetryAfter(headers) {\n  const raw = headers?.get?.('retry-after')\n  if (typeof raw !== 'string' || raw.trim() === '') return undefined\n  const seconds = Number(raw)\n  // 必须 **> 0**，不能 `>= 0`。`dsh-llm` 要求 `providerRetryAfterMs` 是正有限数，\n  // 给 0 会让它构造 LlmError 时抛一句 `providerRetryAfterMs must be a positive finite\n  // number`：真实失败码被替换成无意义消息，`rotationReasonFor` 拿不到 code，于是\n  // **不冷却、不换下一个账户、直接失败** —— 恰好是限流时最需要轮换的场景。\n  // 而且 nginx/Cloudflare/ALB 之类的前置代理在 429/503 上发 `Retry-After: 0` 很常见。\n  // 上界同样必需：畸形或恶意的值会把账户冷却到 ~1e23ms，进程内永久不可用。\n  if (Number.isFinite(seconds) && seconds > 0) return Math.min(Math.trunc(seconds * 1000), RETRY_AFTER_MAX_MS)\n  const date = Date.parse(raw)\n  if (Number.isFinite(date)) {\n    const delta = date - Date.now()\n    return delta > 0 ? Math.min(delta, RETRY_AFTER_MAX_MS) : undefined\n  }\n  return undefined\n}\n\n// ---------------------------------------------------------------------------\n// 适配器\n// ---------------------------------------------------------------------------\n\n/**\n * 火山方舟 Coding Plan 的 LLM 适配器。\n *\n * 依赖通过构造函数注入（配置读取 thunk、密钥解析、附件服务、日志），\n * 所以适配器自身不持有 cordis 上下文，测试也能直接驱动。\n */\nexport class ArkCodingAdapter extends LlmAdapter {\n  constructor(deps) {\n    super()\n    this.deps = deps\n  }\n\n  /** 当前连接事实（每次调用都重新解析，配置改动立即生效）。 */\n  connection() {\n    return resolveConnection(unwrapVolatileConfig(this.deps.config()))\n  }\n\n  providerInfo(provider) {\n    return { id: provider, name: DISPLAY_NAME }\n  }\n\n  /** 默认重试策略：只有瞬时失败会被重试（与 dsh-llm 的默认集合一致）。 */\n  providerRetryPolicy(provider) {\n    return resolveRetryPolicy({ mode: 'normal', maxRetries: 3 }, `providers.${provider}.retryPolicy`)\n  }\n\n  async listModels(_provider) {\n    const connection = this.connection()\n    return MODELS.filter((model) => modelIsVisible(model.id, connection)).map((model) => toModelInfo(model, connection))\n  }\n\n  async resolveModel(_provider, model) {\n    const connection = this.connection()\n    const entry = modelById(model)\n    if (entry === undefined) {\n      // 目录之外的 id 仍然可路由（核心路由不依赖目录），只是没有容量事实。\n      return { provider: PROVIDER, id: model, name: model, inputModalities: ['text'] }\n    }\n    return toResolvedModelInfo(entry, connection)\n  }\n\n  /**\n   * 解析一个凭据引用：字面量优先，其次凭据服务，最后启动环境 / `.env`。\n   *\n   * 密钥永不进日志、不进错误消息；这里只回答\"解析出来了吗\"。\n   *\n   * @param ref - 凭据引用名。\n   * @param literal - 组合配置里的字面量（优先）。\n   * @returns 可用密钥，或 undefined。\n   */\n  async resolveRef(ref, literal) {\n    if (typeof literal === 'string' && literal.trim() !== '') {\n      return assertUsableApiKey(literal, NS, `${NS}（字面量）`)\n    }\n    const ctx = this.deps.ctx?.()\n    const credentials = ctx?.get?.('credentials')\n    if (credentials !== undefined && credentials !== null && isValidRefName(ref)) {\n      // 解不开就往下走 ambient 兜底，不要把整个账户丢掉：`resolve` 本身也可能因为\n      // 后端故障抛错，而\"凭据服务暂时不好用\"不等于\"这个账户没配 key\"。\n      try {\n        const resolved = await credentials.resolve(credentialRef(ref))\n        if (resolved !== undefined && typeof resolved.value === 'string' && resolved.value !== '') {\n          return assertUsableApiKey(resolved.value, NS, ref)\n        }\n      } catch { /* 交给下面的启动环境兜底 */ }\n    }\n    // 没有凭据服务（headless profile）时的兜底：启动环境与 .env。\n    // **`.get()` 返回的是 `{value, source}` 条目，不是字符串** —— 以前这里按字符串读，\n    // 于是这条兜底永远不生效：headless profile 里 export 的 `ARK_CODING_API_KEY` 取不到；\n    // ref 名含 `-`（凭据服务文法拒绝，只能靠环境变量）的账户也取不到，用户只看到\n    // \"账户都还没有可用的 API key\"。一方适配器用的都是 `.get(name)?.value`\n    // （dsh-llm-pi-ai 的 2093 / 2567 行）。\n    const ambient = ctx === undefined ? undefined : launchEnvironmentOf(ctx).get(ref)?.value\n    if (typeof ambient === 'string' && ambient.trim() !== '') {\n      return assertUsableApiKey(ambient, NS, ref)\n    }\n    return undefined\n  }\n\n  /** 解析主账户（保留旧签名：单账户路径）。 */\n  async resolveApiKey() {\n    const connection = this.connection()\n    const accounts = await this.resolveAccounts(connection)\n    return accounts[0]?.key\n  }\n\n  /**\n   * 解析出全部账户及各自的 key，并按「配置偏好 → 可用 → 冷却中」排序。\n   *\n   * 冷却中的账号排在最后而不是被剔除：所有账号都在冷却时，仍然应该去试一次，\n   * 而不是直接报\"没有可用账号\"。\n   */\n  async resolveAccounts(connection = this.connection()) {\n    const marks = this.deps.marks\n    const resolved = []\n    for (const account of connection.accounts) {\n      let key\n      try {\n        // CLI 账户的 key 不在凭据服务里：它是登录后用 arkcli 打印出来的，\n        // 由 deps.cliKey 负责取（带缓存），取不到就当这个账户未配置。\n        key = account.type === TYPE_CLI && this.deps.cliKey !== undefined\n          ? await this.deps.cliKey(account)\n          : await this.resolveRef(account.ref, account.literal)\n      } catch {\n        key = undefined\n      }\n      resolved.push({ ...account, key, usable: marks === undefined ? true : marks.usable(account.id) })\n    }\n    return orderAccounts(resolved, marks ?? { usable: () => true }, connection.activeAccount)\n  }\n\n  /** 面向设置页的账户状态（只回答\"配没配\"，永不回传值）。 */\n  async accountStates() {\n    const connection = this.connection()\n    const ctx = this.deps.ctx?.()\n    const credentials = ctx?.get?.('credentials')\n    const marks = this.deps.marks?.snapshot?.() ?? {}\n    const out = []\n    for (const account of connection.accounts) {\n      const base = {\n        id: account.id,\n        label: account.label,\n        labelIsCustom: account.labelIsCustom === true,\n        type: account.type,\n        ref: account.ref,\n        home: account.type === TYPE_CLI ? account.home : undefined,\n        mark: marks[account.id] ?? null,\n      }\n      if (account.type === TYPE_CLI) {\n        // CLI 账户的\"配没配\"= arkcli 那边登录没登录，key 是登录的副产物。\n        const state = this.deps.cliAccountState === undefined\n          ? { loggedIn: false }\n          : await this.deps.cliAccountState(account)\n        out.push({\n          ...base,\n          configured: state.loggedIn === true,\n          source: state.loggedIn === true ? 'arkcli' : undefined,\n          loggedIn: state.loggedIn === true,\n          credentialExpiresAt: state.credentialExpiresAt,\n          identity: state.identity,\n          needsInstall: state.needsInstall === true,\n        })\n        continue\n      }\n      let configured = account.literal !== undefined\n      let source = account.literal === undefined ? undefined : 'config'\n      if (!configured && credentials !== undefined && credentials !== null && isValidRefName(account.ref)) {\n        try {\n          const info = await credentials.describe(credentialRef(account.ref))\n          if (info?.configured === true) { configured = true; source = info.source ?? 'store' }\n        } catch { /* 描述失败按未配置处理 */ }\n      }\n      if (!configured) {\n        // 同 `resolveRef`：`.get()` 给的是 `{value, source}` 条目，不是字符串。\n        const ambient = ctx === undefined ? undefined : launchEnvironmentOf(ctx).get(account.ref)?.value\n        if (typeof ambient === 'string' && ambient.trim() !== '') { configured = true; source = 'env' }\n      }\n      out.push({ ...base, configured, source })\n    }\n    return out\n  }\n\n  /** 面向设置页的密钥状态（主账户；保留旧签名）。 */\n  async credentialState() {\n    const [first] = await this.accountStates()\n    return { configured: first?.configured === true, source: first?.source }\n  }\n\n  /**\n   * 把请求消息投影成 OpenAI 形状。\n   *\n   * 关键点：\n   * - assistant 历史只回放可见文本与 tool_calls：Ark 的思考字段（`reasoning_content`）\n   *   不接受回灌，回灌会被拒。\n   * - `developer` 消息（工具增删记录）并入 system：Ark 没有 developer 角色，且本适配器\n   *   每次请求都发送完整工具声明，不需要增量语义。\n   * - 每个 tool_call 强制写 `type: 'function'`。这是为了 MiniMax-M3：它回传的\n   *   `tool_calls[].type` 是 `functionfunction`（服务端缺陷），原样回灌会 400。\n   */\n  buildMessages(projected, model, imageUrlFor) {\n    const output = []\n    const imagesAllowed = modalitiesOf(model).includes('image')\n    for (const message of projected) {\n      const blocks = Array.isArray(message.content) ? message.content : []\n      switch (message.role) {\n        case 'system':\n        case 'developer': {\n          const text = blockText(blocks)\n          if (text !== '') output.push({ role: 'system', content: text })\n          break\n        }\n        case 'user': {\n          if (!hasImage(blocks) || !imagesAllowed) {\n            output.push({ role: 'user', content: blockText(blocks) })\n            break\n          }\n          const parts = []\n          for (const block of blocks) {\n            if (block.type === 'text') parts.push({ type: 'text', text: block.text })\n            else if (block.type === 'image') {\n              const url = imageUrlFor?.(block)\n              if (typeof url === 'string') parts.push({ type: 'image_url', image_url: { url } })\n            }\n          }\n          output.push({ role: 'user', content: parts })\n          break\n        }\n        case 'assistant': {\n          const text = blockText(blocks)\n          const toolCalls = blocks\n            .filter((block) => block.type === 'tool-call')\n            .map((block) => ({\n              id: block.id,\n              type: 'function',\n              function: { name: block.name, arguments: block.arguments === '' ? '{}' : block.arguments },\n            }))\n          const entry = { role: 'assistant', content: text }\n          if (toolCalls.length > 0) entry.tool_calls = toolCalls\n          output.push(entry)\n          break\n        }\n        case 'tool': {\n          const callId = message.source?.kind === 'tool' ? message.source.callId : undefined\n          if (callId === undefined) break\n          output.push({ role: 'tool', tool_call_id: callId, content: blockText(blocks) })\n          break\n        }\n        default:\n          break\n      }\n    }\n    return output\n  }\n\n  /** 组一次 `/chat/completions` 的请求体。 */\n  buildBody(options, model, connection, messages) {\n    const body = {\n      model: model?.id ?? options.model,\n      messages,\n      stream: true,\n      stream_options: { include_usage: true },\n    }\n    const cap = model === undefined ? connection.defaultMaxTokens : model.maxOutput\n    const requested = typeof options.maxTokens === 'number' && options.maxTokens > 0 ? Math.trunc(options.maxTokens) : connection.defaultMaxTokens\n    body.max_tokens = Math.max(1, Math.min(requested, cap))\n    if (typeof options.temperature === 'number') body.temperature = options.temperature\n    if (Array.isArray(options.tools) && options.tools.length > 0) {\n      body.tools = options.tools.map((tool) => ({\n        type: 'function',\n        function: { name: tool.name, description: tool.description, parameters: tool.parameters },\n      }))\n    }\n    if (Array.isArray(options.stop) && options.stop.length > 0) body.stop = options.stop\n    const effort = options.reasoningEffort\n    if (typeof effort === 'string' && effort !== '') {\n      const wire = EFFORT_WIRE[effort] ?? effort\n      // GLM-5.3 系列不接受 none；目录里已排除该档位，这里再兜一层。\n      const allowed = model?.efforts?.some((entry) => entry.id === effort) ?? true\n      if (allowed) body.reasoning_effort = wire\n    }\n    return body\n  }\n\n  /** 把一次请求里所有图片读成 data URL，并执行请求体字节预算。 */\n  async projectImages(messages, attachments) {\n    const occurrences = []\n    for (const message of messages) {\n      const blocks = Array.isArray(message.content) ? message.content : []\n      for (const block of blocks) {\n        if (block.type === 'image' && block.offloaded !== true) occurrences.push(block)\n      }\n    }\n    const byId = new Map()\n    const urls = new Map()\n    for (const block of occurrences) {\n      const ref = block.attachment\n      if (ref === undefined || typeof ref.attachmentId !== 'string') continue\n      if (urls.has(ref.attachmentId)) continue\n      const target = {\n        ...projectImageSize(ref.width, ref.height, REQUEST_IMAGE_MAX_LONG_EDGE),\n        maxBytes: REQUEST_IMAGE_MAX_ENCODED_BYTES,\n      }\n      const version = await attachments.readImageRequest(ref, target)\n      // 存**原始编码字节**，不是 base64 长度：`requiredImageOffload` 的回调要的是原始字节，\n      // base64 展开由它自己做（`dsh-llm` 的 content.js 会按 representation==='base64' 再展开）。\n      // 以前这里预先展开过一次，于是同一张图被算了两遍，报出的 missing 比真实多，\n      // 上层就**永久**多卸载一张图 —— 不可逆的上下文丢失，模型再也看不到它。\n      byId.set(ref.attachmentId, imageBytesOf(version))\n      urls.set(ref.attachmentId, dataUrl(version.mediaType, version.data))\n    }\n    // 自检口径要与真正发出去的 body 一致：同一附件被引用两次，data URL 就会在 body 里\n    // 出现两次，所以这里按**出现次数**累加（旧实现按 attachmentId 去重，会漏算一半）。\n    const encodedTotal = occurrences.reduce((sum, block) => {\n      const bytes = byId.get(block.attachment?.attachmentId)\n      return sum + (typeof bytes === 'number' ? base64LengthOf(bytes) : 0)\n    }, 0)\n    if (encodedTotal > DEFAULT_MAX_REQUEST_IMAGE_BYTES) {\n      const budget = {\n        representation: 'base64',\n        maxBytes: DEFAULT_MAX_REQUEST_IMAGE_BYTES,\n        byteQuantum: 1,\n        countQuantum: 1,\n      }\n      const missing = requiredImageOffload(messages, budget, (block) => byId.get(block.attachment?.attachmentId) ?? 0)\n      throw new LlmError(\n        `请求中的图片超过单次上限，需要先卸载最旧的 ${missing} 张图片后再重试。`,\n        'IMAGE_OFFLOAD_REQUIRED',\n        { offloadImages: missing },\n      )\n    }\n    return urls\n  }\n\n  /**\n   * 一次请求里与账号无关的部分：图片投影、消息翻译、请求体。\n   * 多账户轮换时只准备一次，换账号只是换 `Authorization`。\n   */\n  async prepare(options, connection, model) {\n    // 被上层标记为 offloaded 的图片先降级成占位文本，剩下的才真正内联。\n    const projected = projectOffloadedImages(options.messages, (ref) => offloadedImageText(ref))\n\n    let imageUrls = new Map()\n    if (projected.some((message) => Array.isArray(message.content) && hasImage(message.content))) {\n      const attachments = this.deps.attachments?.()\n      if (attachments === undefined || attachments === null) {\n        throw new LlmError('图片输入需要宿主挂载附件服务', 'UNSUPPORTED_CONTENT')\n      }\n      imageUrls = await this.projectImages(projected, attachments)\n    }\n\n    // 图片 URL 只属于这一次请求：并发调用（例如会话标题生成）各带各的映射，\n    // 绝不挂在适配器实例上。\n    const imageUrlFor = (block) => imageUrls.get(block.attachment?.attachmentId)\n    const messages = this.buildMessages(projected, model, imageUrlFor)\n    // `options.system` 是**一次性调用**的指令入口：`dsh-session-title-llm`（标题的语言/\n    // 格式约束）与 `dsh-experimental-auto-review`（`system` 就是风险分类策略本体）都只把\n    // 指令放在这里，messages 里只有用户文本。契约要求适配器把它映射到 provider 的\n    // system 槽并排在 messages 之前，两个一方适配器都这么做；忽略它等于让那些路径在\n    // **没有任何系统指令**的情况下作答 —— 对 Auto Review 来说是安全相关的降级。\n    if (typeof options.system === 'string' && options.system.trim() !== '') {\n      messages.unshift({ role: 'system', content: options.system })\n    }\n    return { body: this.buildBody(options, model, connection, messages) }\n  }\n\n  /**\n   * 唯一的必需方法：把一次模型调用流成 StreamChunk。\n   *\n   * 多账户轮换发生在这里：按顺序试每个可用账号，**只要还没吐出任何 chunk**，\n   * 就把「限流 / 额度用尽 / key 不可用」当成换账号的信号；一旦开始吐内容，\n   * 换账号重来会把半截回答重复一遍，所以那时一律原样抛出。\n   */\n  async *stream(options) {\n    const connection = this.connection()\n    const model = modelById(options.model)\n    const accounts = await this.resolveAccounts(connection)\n    if (accounts.length === 0) {\n      // 现在没有\"默认账户\"了，所以这里要区分两种空：压根没有账户 vs 有账户但都没配好。\n      // 顺带把\"怎么修\"说到具体动作上，而不是丢一句\"没有 API key\"。\n      const exists = connection.accounts.length > 0\n      throw new LlmError(\n        exists\n          ? `${DISPLAY_NAME} 的账户都还没有可用的 API key：去「设置 → 火山方舟」，`\n            + '给 API Key 账户填上密钥，或给 CLI 账户完成登录。'\n          : `${DISPLAY_NAME} 还没有任何账户：去「设置 → 火山方舟」点「添加账户」，`\n            + '选「CLI 登录」能顺带拿到真实套餐额度，选「API Key」则只够聊天。',\n        'MISSING_CREDENTIAL',\n      )\n    }\n\n    const prepared = await this.prepare(options, connection, model)\n    const marks = this.deps.marks\n    let lastError\n\n    for (const account of accounts) {\n      const state = { emitted: false }\n      try {\n        for await (const chunk of this.streamOnce(options, connection, model, prepared, account)) {\n          state.emitted = true\n          yield chunk\n        }\n        marks?.clear(account.id)\n        return\n      } catch (error) {\n        if (options.signal?.aborted === true) throw error\n        const code = error instanceof LlmError ? error.code : undefined\n        const reason = rotationReasonFor(code)\n        // 已经吐过内容、或者这个失败换账号也没用 → 原样抛出去。\n        if (reason === undefined || state.emitted) throw error\n        const cooldown = retryAfterMsOf(error?.failure) ?? cooldownFor(reason)\n        marks?.mark(account.id, reason, Date.now() + cooldown)\n        lastError = error\n        this.deps.logger?.warn?.(\n          `${NS}: 账户「${account.label}」${reason}（${code}），冷却 ${Math.round(cooldown / 1000)}s 后重试，先切到下一个账户`,\n        )\n      }\n    }\n\n    throw lastError ?? new LlmError(`${DISPLAY_NAME} 的所有账户都不可用。`, 'QUOTA')\n  }\n\n  /** 用某一个账号发一次请求，把响应流交给调用方。 */\n  async *streamOnce(options, connection, model, prepared, account) {\n    const controller = new AbortController()\n    const onAbort = () => controller.abort(options.signal?.reason)\n    if (options.signal !== undefined) {\n      if (options.signal.aborted) controller.abort(options.signal.reason)\n      else options.signal.addEventListener('abort', onAbort, { once: true })\n    }\n    const headTimer = setTimeout(() => controller.abort(new Error('request timeout')), connection.requestTimeoutMs)\n\n    let response\n    try {\n      response = await fetch(`${connection.apiBase}/chat/completions`, {\n        method: 'POST',\n        headers: {\n          'content-type': 'application/json',\n          accept: 'text/event-stream',\n          authorization: `Bearer ${account.key}`,\n          ...attributionHeaders(),\n        },\n        body: JSON.stringify(prepared.body),\n        signal: controller.signal,\n      })\n    } catch (error) {\n      clearTimeout(headTimer)\n      options.signal?.removeEventListener?.('abort', onAbort)\n      if (options.signal?.aborted === true) throw abortError(options.signal)\n      const timedOut = controller.signal.aborted\n      throw new LlmError(\n        timedOut\n          ? `${DISPLAY_NAME} 在 ${connection.requestTimeoutMs} ms 内没有返回响应头。`\n          : `无法连接 ${DISPLAY_NAME}：${error instanceof Error ? error.message : String(error)}`,\n        timedOut ? 'TIMEOUT' : 'TRANSPORT',\n        { cause: error },\n      )\n    }\n\n    clearTimeout(headTimer)\n    try {\n      if (!response.ok) {\n        const text = await safeText(response)\n        const detail = errorDetail(text)\n        const requestId = requestIdOf(text)\n        const retryAfter = parseRetryAfter(response.headers)\n        if (response.status === 401 || response.status === 403) {\n          throw new LlmError(\n            `${DISPLAY_NAME} 拒绝了这个 API key（HTTP ${response.status}）。请确认它是 Coding Plan 的密钥。`,\n            'AUTH',\n            { status: response.status, requestId, ...(retryAfter === undefined ? {} : { providerRetryAfterMs: retryAfter }) },\n          )\n        }\n        // 分类用**完整**响应体，展示才用截断后的 detail：额度/上下文这类判定依赖\n        // 错误关键字，而关键字有时代码/请求 id 之后（`errorDetail` 只留前 400 字符，\n        // 拿它去分类会让一个本该 QUOTA 的失败退化成 PROVIDER_ERROR）。\n        const failure = classifyHttpFailure(response.status, text, requestId)\n        throw new LlmError(\n          failure.message + (detail === '' ? '' : `：${detail}`),\n          failure.code,\n          { status: response.status, requestId, ...(retryAfter === undefined ? {} : { providerRetryAfterMs: retryAfter }) },\n        )\n      }\n      for await (const chunk of this.parseStream(response, connection, options)) {\n        yield chunk\n      }\n    } finally {\n      options.signal?.removeEventListener?.('abort', onAbort)\n    }\n  }\n\n  /**\n   * 解析 SSE 流并产出 StreamChunk。\n   *\n   * 这里只做出口兜底：真正的解析在 `parseStreamRaw`，本方法保证交出去的每一块都\n   * 是\"无损 JSON\"（见 `withoutUndefined`）。\n   */\n  async *parseStream(response, connection, options) {\n    for await (const chunk of this.parseStreamRaw(response, connection, options)) {\n      yield withoutUndefined(chunk)\n    }\n  }\n\n  /** 真正的 SSE 解析。别的地方不要直接调它 —— 必须经过 `parseStream` 的出口兜底。 */\n  async *parseStreamRaw(response, connection, options) {\n    const reader = response.body?.getReader()\n    if (reader === undefined) {\n      throw new LlmError('火山方舟返回了空的响应体', 'TRANSPORT')\n    }\n    const decoder = new TextDecoder()\n    let buffer = ''\n    let idleTimer\n    /** 空闲超时不是\"正常结束\"：它必须被报出来，不能悄悄截断成一次成功的补全。 */\n    let idleExpired = false\n    const armIdle = () => {\n      if (idleTimer !== undefined) clearTimeout(idleTimer)\n      idleTimer = setTimeout(() => {\n        idleExpired = true\n        // 必须吞掉拒绝：`cancel()` 拒绝时就是一个未处理 rejection，而 DSH 把\n        // unhandledRejection 当致命错误（`dsh-app-boot` 的 report() → proc.exit(1)）。\n        // 同一个调用在下面的 finally 里是包了 try/catch 的，这里当时漏了。\n        try {\n          const cancelled = reader.cancel(new Error('stream idle timeout'))\n          if (typeof cancelled?.catch === 'function') cancelled.catch(() => {})\n        } catch { /* 流已经崩了，没什么可取消的 */ }\n      }, connection.streamIdleTimeoutMs)\n    }\n\n    let nextIndex = 0\n    let reasoningIndex = -1\n    let textIndex = -1\n    let reasoningText = ''\n    let text = ''\n    const toolBlocks = new Map()\n    let usage\n    let finishReason = 'stop'\n    let produced = false\n    /** 见过 `finish_reason` 或 `[DONE]` 吗？没见过就结束 = 截断，不能算一次正常的 stop。 */\n    let sawTerminal = false\n    /** 见过 `[DONE]`：之后的数据是上游重复/补发，必须丢掉。 */\n    let sawDone = false\n    /** 读到流末尾了（`read()` 返回 done）。用来在冲完残留缓冲后退出循环。 */\n    let sawEnd = false\n    /** 读取途中抛出的错（含上游断连）。延后到空闲超时判定之后再决定怎么报。 */\n    let streamError\n\n    const openBlock = (blockType) => {\n      const index = nextIndex++\n      if (blockType === 'reasoning') reasoningIndex = index\n      else if (blockType === 'text') textIndex = index\n      return index\n    }\n\n    try {\n      armIdle()\n      for (;;) {\n        const { done, value } = await reader.read()\n        if (done) {\n          // 流结束：把解码器和残留缓冲一起冲干净。最后一帧**可能没有换行**（旧代理、\n          // 自研网关、被截断的连接都会这样），而旧实现只在 `indexOf('\\n')` 命中时才处理，\n          // 于是那一帧连同末尾半个多字节字符一起被静默丢掉 —— 少字却报成功。\n          // 补一个换行，让下面同一套行处理逻辑把它吃掉；处理完就退出循环。\n          buffer += `${decoder.decode()}\\n`\n          sawEnd = true\n        } else {\n          armIdle()\n          buffer += decoder.decode(value, { stream: true })\n          // 单条行的上限，见 MAX_SSE_LINE_BYTES 的注释。\n          if (buffer.length > MAX_SSE_LINE_BYTES) {\n            throw new LlmError(\n              `${DISPLAY_NAME} 返回的单条 SSE 数据超过 ${MAX_SSE_LINE_BYTES} 字节，已中断本次请求。`,\n              'PROVIDER_ERROR',\n            )\n          }\n        }\n        let newline = buffer.indexOf('\\n')\n        while (newline !== -1) {\n          const line = buffer.slice(0, newline).replace(/\\r$/, '')\n          buffer = buffer.slice(newline + 1)\n          newline = buffer.indexOf('\\n')\n          if (!line.startsWith('data:')) continue\n          const payload = line.slice(5).trim()\n          if (payload === '') continue\n          if (payload === '[DONE]') {\n            // 收到终止标记就停：DONE 之后的数据是上游重复/补发，拼进回答里就是脏内容。\n            sawDone = true\n            sawTerminal = true\n            break\n          }\n          let frame\n          try {\n            frame = JSON.parse(payload)\n          } catch {\n            continue\n          }\n          const frameError = frame.error\n          // 错误帧有两种形状：对象（一次失败）与字符串（上游/网关更常这么写）。\n          // 旧实现只认对象，字符串形式的错误被**完全吞掉** —— 一次本该失败的调用\n          // 变成一次\"成功的半截回答\"。\n          if (isPlainObject(frameError) || (typeof frameError === 'string' && frameError !== '')) {\n            const detail = errorDetail(payload) || (typeof frameError === 'string' ? frameError : '')\n            throw new LlmError(`火山方舟在流中报错：${detail}`, isQuotaExceededError(detail) ? 'QUOTA' : 'PROVIDER_ERROR', {\n              requestId: requestIdOf(payload),\n            })\n          }\n          if (isPlainObject(frame.usage)) usage = frame.usage\n          const choice = Array.isArray(frame.choices) ? frame.choices[0] : undefined\n          if (!isPlainObject(choice)) continue\n          if (typeof choice.finish_reason === 'string' && choice.finish_reason !== '') {\n            finishReason = choice.finish_reason\n            sawTerminal = true\n          }\n          const delta = choice.delta\n          if (!isPlainObject(delta)) continue\n\n          const reasoning = delta.reasoning_content\n          if (typeof reasoning === 'string' && reasoning !== '') {\n            if (reasoningIndex === -1) {\n              const index = openBlock('reasoning')\n              yield { type: 'block-start', index, blockType: 'reasoning' }\n            }\n            reasoningText += reasoning\n            produced = true\n            yield { type: 'reasoning-delta', index: reasoningIndex, text: reasoning }\n          }\n\n          const content = delta.content\n          if (typeof content === 'string' && content !== '') {\n            if (textIndex === -1) {\n              const index = openBlock('text')\n              yield { type: 'block-start', index, blockType: 'text' }\n            }\n            text += content\n            produced = true\n            yield { type: 'text-delta', index: textIndex, text: content }\n          }\n\n          if (Array.isArray(delta.tool_calls)) {\n            for (const call of delta.tool_calls) {\n              if (!isPlainObject(call)) continue\n              const key = typeof call.index === 'number' ? call.index : toolBlocks.size\n              let entry = toolBlocks.get(key)\n              if (entry === undefined) {\n                // 块声明只带 index 与 blockType，所以这里先开块；id/name 随增量补齐，\n                // 收块时用累积值落地（见下面的 block-end）。\n                const index = openBlock('tool-call')\n                entry = { index, id: '', name: '', arguments: '' }\n                toolBlocks.set(key, entry)\n                yield { type: 'block-start', index, blockType: 'tool-call' }\n              }\n              const fn = isPlainObject(call.function) ? call.function : undefined\n              if (entry.id === '' && typeof call.id === 'string' && call.id !== '') entry.id = call.id\n              const nameDelta = typeof fn?.name === 'string' ? fn.name : ''\n              const argsDelta = typeof fn?.arguments === 'string' ? fn.arguments : ''\n              if (entry.name === '' && nameDelta !== '') entry.name = nameDelta\n              entry.arguments += argsDelta\n              produced = true\n              yield {\n                type: 'tool-call-delta',\n                index: entry.index,\n                id: entry.id === '' ? `call_${entry.index}` : entry.id,\n                ...(nameDelta === '' ? {} : { name: nameDelta }),\n                argumentsDelta: argsDelta,\n              }\n            }\n          }\n        }\n        // `[DONE]` 之后不再消费数据；读到流末尾冲完残留缓冲也要退出。\n        // （这两个条件缺一不可：只判 `[DONE]` 的话，一个没有终止标记就结束的流\n        // 会让 `reader.read()` 永远返回 done，循环变成忙等 —— 实测直接把进程挂死。）\n        if (sawDone || sawEnd) break\n      }\n    } catch (error) {\n      streamError = error\n    } finally {\n      if (idleTimer !== undefined) clearTimeout(idleTimer)\n      try { await reader.cancel() } catch { /* 流已结束 */ }\n    }\n\n    // 空闲超时先于收块判定：这时流是被我们主动掐掉的，内容不完整，\n    // 报成 TIMEOUT 交给重试器，而不是当作一次正常的短回答落地。\n    if (idleExpired) {\n      throw new LlmError(\n        `${DISPLAY_NAME} 的响应流空闲超过 ${connection.streamIdleTimeoutMs} ms，已中断本次请求。`,\n        'TIMEOUT',\n      )\n    }\n\n    if (streamError !== undefined) {\n      if (options.signal?.aborted === true) throw abortError(options.signal)\n      if (streamError instanceof LlmError) throw streamError\n      // 上游中途断连时 undici 抛的是裸 `TypeError: terminated`：对用户毫无意义，\n      // 重试器也认不出它，所以统一包成 TRANSPORT（可重试）。\n      throw new LlmError(\n        `${DISPLAY_NAME} 的响应流中断：${streamError instanceof Error ? streamError.message : String(streamError)}`,\n        'TRANSPORT',\n        { cause: streamError },\n      )\n    }\n\n    // 收块：BlockAssembler 用 block-end 的完整块落地。\n    if (reasoningIndex !== -1) {\n      yield { type: 'block-end', index: reasoningIndex, block: { type: 'reasoning', text: reasoningText } }\n    }\n    if (textIndex !== -1) {\n      yield { type: 'block-end', index: textIndex, block: { type: 'text', text } }\n    }\n    for (const entry of toolBlocks.values()) {\n      yield {\n        type: 'block-end',\n        index: entry.index,\n        block: {\n          type: 'tool-call',\n          id: entry.id === '' ? `call_${entry.index}` : entry.id,\n          name: entry.name,\n          arguments: entry.arguments === '' ? '{}' : entry.arguments,\n        },\n      }\n    }\n\n    if (usage !== undefined) yield { type: 'usage', usage: normalizeUsage(usage) }\n\n    if (!produced) {\n      throw new LlmError(`${DISPLAY_NAME} 返回了没有任何内容的一次补全（finish_reason=${finishReason}）。`, EMPTY_RESPONSE_CODE)\n    }\n\n    // 流被**干净地**关闭、但既没有 `finish_reason` 也没有 `[DONE]`：这是截断，不是完成。\n    // 上游或中间代理在生成中途优雅关掉响应体（FIN 无错）时很常见；旧实现把它当成一次\n    // 正常的 `stop`，于是半截回答被当作完整回答落地，重试策略也不会介入 ——\n    // \"少字却报成功\"比直接报错危险得多。报成 TRANSPORT 交给重试器。\n    if (!sawTerminal) {\n      throw new LlmError(\n        `${DISPLAY_NAME} 的响应流在没有 finish_reason / [DONE] 的情况下结束了，回答可能不完整。`,\n        'TRANSPORT',\n      )\n    }\n\n    yield { type: 'finish', reason: finishReasonOf(finishReason) }\n  }\n}\n\n/** Ark 的 finish_reason → DSH 的 FinishReason。 */\nfunction finishReasonOf(reason) {\n  if (reason === 'tool_calls' || reason === 'function_call') return { kind: 'tool-calls' }\n  if (reason === 'length' || reason === 'max_tokens') return { kind: 'max-tokens' }\n  return { kind: 'stop' }\n}\n\n/**\n * Ark 的 usage → DSH 的 TokenUsage。\n *\n * DSH 的计数是不相交的：`inputTokens` 只算未命中缓存的输入，缓存命中单独报。\n * Ark 的 `prompt_tokens` 是含缓存的总量，所以要减出来。\n */\nfunction normalizeUsage(usage) {\n  const prompt = countOr(usage.prompt_tokens)\n  const cached = countOr(usage.prompt_tokens_details?.cached_tokens)\n  const output = countOr(usage.completion_tokens)\n  const reasoning = countOr(usage.completion_tokens_details?.reasoning_tokens)\n  const result = {\n    inputTokens: Math.max(0, prompt - cached),\n    outputTokens: output,\n  }\n  if (cached > 0) result.cacheReadTokens = cached\n  if (reasoning > 0) result.reasoningTokens = reasoning\n  // total 也要过同一道闸：harness 的 tokenUsage 投影要求 non-negative int，\n  // 见 countOr 的注释。\n  if (usage.total_tokens !== undefined) result.totalTokens = countOr(usage.total_tokens)\n  return result\n}\n\n/**\n * 上游计数 → harness 能接受的 token 数：**非负安全整数**，否则 `undefined`（当作没报）。\n *\n * 为什么不能只查 `Number.isFinite`：`dsh-token-meter` 的投影 schema 要求 non-negative\n * integer，而 `viewSchema.parse` 在会话快照/冷恢复路径上没有 try/catch。实测把\n * `outputTokens: -7` 或 `1e308` 或小数透传过去，投影直接 `state=INVALID` 且 `view` 抛错，\n * 打挂的是**整个会话的用量视图**，而不只是这一条数字。脏数据可能来自上游 bug，\n * 也可能来自被劫持的网关，所以这里必须自己兜住。\n */\nfunction countOr(value) {\n  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0) return 0\n  return value\n}\n\n/** 附件服务给的原始编码字节数；`bytes` 缺失时从 data 自身量。 */\nfunction imageBytesOf(version) {\n  if (typeof version?.bytes === 'number' && Number.isFinite(version.bytes) && version.bytes >= 0) return version.bytes\n  try { return Buffer.from(version?.data ?? []).length } catch { return 0 }\n}\n\n/** base64 编码后的字符数（不含 padding 误差，按标准 4/3 上取整）。 */\nfunction base64LengthOf(bytes) {\n  return Math.ceil(Math.max(0, bytes) / 3) * 4\n}\n\nasync function safeText(response) {\n  try {\n    return await response.text()\n  } catch {\n    return ''\n  }\n}\n\nfunction abortError(signal) {\n  return new LlmError('请求已取消', 'ABORTED', { cause: signal.reason })\n}\n\n// ---------------------------------------------------------------------------\n// 模型发现（Host 侧联机自检）\n// ---------------------------------------------------------------------------\n\n/**\n * 设置页「测试连接」背后的 Host 侧询问：用一次性密钥真的打一次 Coding Plan 端点。\n *\n * 这一步存在的意义是让浏览器不必持有密钥就能验证连通性：密钥只在这一个请求的\n * 生命周期里存在，宿主不存储它。成功则顺带回答这 12 个模型的容量事实。\n */\nexport function createDiscovery() {\n  return async function discover(request, signal) {\n    const baseURL = (typeof request.baseURL === 'string' && request.baseURL.trim() !== ''\n      ? request.baseURL.trim()\n      : DEFAULT_API_BASE).replace(/\\/+$/, '')\n    const apiKey = typeof request.apiKey === 'string' ? normalizeApiKey(request.apiKey) : { ok: false, reason: 'empty' }\n    if (apiKey.ok === false) {\n      throw new Error('请先填入 API key 再测试连接。')\n    }\n    const controller = new AbortController()\n    const onAbort = () => controller.abort(signal?.reason)\n    if (signal !== undefined) {\n      if (signal.aborted) controller.abort(signal.reason)\n      else signal.addEventListener('abort', onAbort, { once: true })\n    }\n    const timer = setTimeout(() => controller.abort(new Error('timeout')), 30_000)\n    let response\n    try {\n      response = await fetch(`${baseURL}/chat/completions`, {\n        method: 'POST',\n        headers: {\n          'content-type': 'application/json',\n          accept: 'application/json',\n          authorization: `Bearer ${apiKey.value}`,\n          ...attributionHeaders(),\n        },\n        body: JSON.stringify({\n          model: 'doubao-seed-2.0-mini',\n          messages: [{ role: 'user', content: 'ping' }],\n          max_tokens: 1,\n          thinking: { type: 'disabled' },\n        }),\n        signal: controller.signal,\n      })\n    } catch (error) {\n      throw new Error(`无法连接 ${baseURL}：${error instanceof Error ? error.message : String(error)}`)\n    } finally {\n      clearTimeout(timer)\n      signal?.removeEventListener?.('abort', onAbort)\n    }\n    if (!response.ok) {\n      const text = await safeText(response)\n      throw new Error(`HTTP ${response.status}：${errorDetail(text) || text.slice(0, 200)}`)\n    }\n    await safeText(response)\n    return MODELS.map((model) => ({\n      id: model.id,\n      name: model.name,\n      contextWindow: model.contextWindow,\n      maxTokens: model.maxOutput,\n      inputModalities: modalitiesOf(model),\n    }))\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 用量 Remote（宿主 → 浏览器）\n// ---------------------------------------------------------------------------\n\n/** npm 包身份，Host 贡献与 Client 挂载必须一致。 */\nexport const REMOTE_PACKAGE = 'dsh-ark-coding-provider'\n/** Gateway 解析的 Cordis 服务键，也是默认线网命名空间。 */\nexport const REMOTE_SERVICE = 'arkCodingUsage'\n/** 与 llm-ark-coding 区分开：这是浏览器要调的自定义命名空间。 */\nexport const REMOTE_NAMESPACE = 'arkcoding'\n\n/** 边界 schema：只保证\"是个对象\"，字段由两侧的 TS 形状约定。 */\nfunction objectSchema(label) {\n  return {\n    parse(value) {\n      if (typeof value !== 'object' || value === null || Array.isArray(value)) {\n        throw new TypeError(`${label}: 结果不是对象`)\n      }\n      return value\n    },\n  }\n}\n\n/** 无参数端点的结果 schema。 */\nfunction resultOf(method) {\n  return {\n    mode: 'strict',\n    typeSymbol: `${REMOTE_PACKAGE}#arkcoding/${method}:result`,\n    create: () => objectSchema(`arkcoding/${method}`),\n  }\n}\n\n/**\n * 一个收 JSON 参数的端点。\n *\n * codec 必须是 `mode: 'strict'`。协议里还有个 `{ mode: 'src-json' }` 的\"不校验\"\n * 档（宿主网关内部自己就用它），但**客户端**的贡献校验只收 strict —— 用它会让\n * 整个 `$mount` 抛 `field \"input\" has no strict codec`，代价是**八个端点全部失效**、\n * 用量卡片永远停在 Loading。所以这里给一个\"恒真的 strict\"：结构上合规，语义上\n * 仍然不预设字段（这些参数本来就没有可枚举的静态类型，真正的校验在宿主方法里做，\n * 报错信息也更贴近用户看到的东西）。\n *\n * `name` 与 `wire` 都写成 `input`：客户端代理无论按哪个字段映射，落到线上都是 `input`。\n */\nfunction actionOf(method) {\n  return {\n    id: `${REMOTE_PACKAGE}#${REMOTE_NAMESPACE}/${method}`,\n    service: REMOTE_SERVICE,\n    namespace: REMOTE_NAMESPACE,\n    method,\n    invocation: { kind: 'direct' },\n    parameters: [{\n      name: 'input',\n      wire: 'input',\n      source: 'json',\n      codec: {\n        mode: 'strict',\n        typeSymbol: `${REMOTE_PACKAGE}#${REMOTE_NAMESPACE}/${method}:input`,\n        create: () => objectSchema(`${method} input`),\n      },\n    }],\n    result: resultOf(method),\n  }\n}\n\n/** 无参数端点的描述符。 */\nfunction plainOf(method) {\n  return {\n    id: `${REMOTE_PACKAGE}#${REMOTE_NAMESPACE}/${method}`,\n    service: REMOTE_SERVICE,\n    namespace: REMOTE_NAMESPACE,\n    method,\n    invocation: { kind: 'direct' },\n    parameters: [],\n    result: resultOf(method),\n  }\n}\n\n/** 账户 + 用量 + 官方目录 + arkcli 状态的汇总（侧边栏与设置页共用）。 */\nexport const USAGE_REPORT_DESCRIPTOR = plainOf('report')\n/** arkcli 是否可用、装在哪、什么版本。 */\nexport const CLI_STATUS_DESCRIPTOR = plainOf('cliStatus')\n/** 一键把 arkcli 装进插件私有目录。 */\nexport const CLI_INSTALL_DESCRIPTOR = plainOf('cliInstall')\n/** 强制刷新官方模型目录。 */\nexport const CATALOG_REFRESH_DESCRIPTOR = plainOf('catalogRefresh')\n/** 开始一次 CLI 无浏览器登录，拿回授权 URL。 */\nexport const LOGIN_BEGIN_DESCRIPTOR = actionOf('loginBegin')\n/** 轮询登录状态（用户可能在浏览器那边花了很久）。 */\nexport const LOGIN_POLL_DESCRIPTOR = actionOf('loginPoll')\n/** 把用户从浏览器地址栏复制的回跳 URL（或授权码）交给 arkcli 完成登录。 */\nexport const LOGIN_SUBMIT_DESCRIPTOR = actionOf('loginSubmit')\n/** 取消一次进行中的登录。 */\nexport const LOGIN_CANCEL_DESCRIPTOR = actionOf('loginCancel')\n\n/** 浏览器通过 `remote.arkcoding.*` 能调到的全部端点。 */\nexport const USAGE_CLIENT_CONTRIBUTION = {\n  package: REMOTE_PACKAGE,\n  descriptors: [\n    USAGE_REPORT_DESCRIPTOR,\n    CLI_STATUS_DESCRIPTOR,\n    CLI_INSTALL_DESCRIPTOR,\n    CATALOG_REFRESH_DESCRIPTOR,\n    LOGIN_BEGIN_DESCRIPTOR,\n    LOGIN_POLL_DESCRIPTOR,\n    LOGIN_SUBMIT_DESCRIPTOR,\n    LOGIN_CANCEL_DESCRIPTOR,\n  ],\n}\n\n/**\n * Remote 接收者：一个 Cordis 服务，Gateway 按 key 解析它、按命名空间绑定线网。\n * 基类负责盖 `typertRemote` 绑定，不需要装饰器 —— 描述符是显式注册的。\n *\n * 每个方法都只负责把参数转交给 `deps`：真正的逻辑（以及它需要的 cordis 上下文、\n * 子进程、缓存）留在 `apply()` 里，那里才拿得到活的配置与 logger。\n */\nexport class ArkCodingUsageService extends TypertRemoteService {\n  constructor(ctx, deps) {\n    super(ctx, REMOTE_SERVICE, { namespace: REMOTE_NAMESPACE })\n    this.deps = deps\n  }\n\n  /** 账户 + 套餐额度 + 官方目录。 */\n  async report() {\n    return this.deps.report()\n  }\n\n  /** arkcli 探测结果。 */\n  async cliStatus() {\n    return this.deps.cliStatus()\n  }\n\n  /** 装 arkcli（幂等：已装就直接返回现状）。 */\n  async cliInstall() {\n    return this.deps.cliInstall()\n  }\n\n  /** 刷新官方模型目录。 */\n  async catalogRefresh() {\n    return this.deps.catalogRefresh()\n  }\n\n  /** 开始登录，返回授权 URL。 */\n  async loginBegin(input) {\n    return this.deps.loginBegin(input ?? {})\n  }\n\n  /** 查这次登录到哪一步了。 */\n  async loginPoll(input) {\n    return this.deps.loginPoll(input ?? {})\n  }\n\n  /** 把回跳 URL / 授权码喂回去，完成登录。 */\n  async loginSubmit(input) {\n    return this.deps.loginSubmit(input ?? {})\n  }\n\n  /** 放弃这次登录。 */\n  async loginCancel(input) {\n    return this.deps.loginCancel(input ?? {})\n  }\n}\n\n/** 把任意抛出物渲染成一行可读文字（供页面显示）。 */\nfunction errorText(error) {\n  if (error instanceof Error) return error.message\n  return typeof error === 'string' ? error : String(error)\n}\n\n// ---------------------------------------------------------------------------\n// 插件入口\n// ---------------------------------------------------------------------------\n\n/** 挂载适配器、可配置提供商目录、模型发现与用量 Remote。 */\n/** Coding Plan 在 `usage plan` 里的 product id。 */\nconst CODING_PRODUCT = 'coding-plan'\n\n/** 额度窗口 key → 界面上显示的名字。 */\nconst WINDOW_LABELS = { session: '5 小时', weekly: '本周', monthly: '本月' }\n\n/**\n * 从 `arkcli usage plan` 的 items 里挑出 Coding Plan 的窗口。\n *\n * 只认 `coding-plan`：Agent Plan 的额度是另一套口径（它给绝对值，Coding Plan\n * 只给百分比），混在一起显示会让人以为看到的是同一个池子。没订阅就如实说明，\n * 顺便告诉用户他订的到底是什么 —— 比一个干巴巴的\"没有数据\"有用。\n */\nfunction windowsFromItems(items) {\n  const list = Array.isArray(items) ? items : []\n  const coding = list.filter((item) => item.product === CODING_PRODUCT && item.subscribed === true)\n  if (coding.length === 0) {\n    const others = [...new Set(list.filter((item) => item.subscribed === true).map((item) => item.product))]\n    return {\n      windows: [],\n      error: others.length > 0\n        ? `这个账号订阅的是 ${others.join(' / ')}，不是 Coding Plan。`\n        : '这个账号没有查到生效中的 Coding Plan 订阅。',\n    }\n  }\n  const item = coding[0]\n  return {\n    windows: (Array.isArray(item.periods) ? item.periods : []).map((period) => ({\n      key: period.key,\n      label: WINDOW_LABELS[period.key] ?? period.label ?? period.key,\n      percent: period.percent,\n      used: period.used,\n      total: period.total,\n      hasTotals: period.hasTotals === true,\n      resetAt: period.resetAt,\n    })),\n    tier: item.tier,\n    updatedAt: item.updatedAt,\n  }\n}\n\nexport function apply(ctx, config) {\n  // 关掉 settings 的\"自动页面\"：本插件自带设置分区，不需要再按原始 schema 生成一份\n  // 表单页。官方 provider 插件（dsh-llm-deepseek / dsh-llm-pi-ai）都这么做。这份自动页\n  // 会直接暴露 `apiKeyEnv` / `secretAccessKeyEnv` 这类凭据引用字段，与插件自己的 UI 重复。\n  ctx.inject(['settings'], (child) => {\n    child.effect(() => child.settings.configure({ auto: false }, ctx.fiber))\n  })\n\n  const marks = new AccountMarks()\n  // DSH_HOME 是插件所有持久状态的根（arkcli 的托管安装、各账户的 HOME）。\n  // 理论上它一定存在（systemd 单元里写了），但缺了的时候我们要给一句人话，\n  // 而不是从 `path.join(undefined, …)` 里抛一个 TypeError 出来。\n  const dshHome = typeof process.env.DSH_HOME === 'string' && process.env.DSH_HOME.trim() !== ''\n    ? process.env.DSH_HOME.trim()\n    : undefined\n  const NO_DSH_HOME = '没有 DSH_HOME：无法确定插件状态目录，CLI 账户不可用。'\n\n  /** 当前配置的普通值快照（每次都新鲜）。 */\n  const live = () => unwrapVolatileConfig(config)\n\n  /**\n   * arkcli 进程封装：探测、安装、取额度、取目录。\n   *\n   * `binPath` 来自配置的 `arkcliPath`。**以前这个字段从来没有传进来过**：它被读进\n   * `resolveConnection` 之后就再无消费者，`ArkCli` 的 `binPath` 分支永不命中，\n   * 文档承诺的\"显式指定 arkcli 可执行文件\"是空头支票 —— 实际只会去找托管目录和\n   * PATH，而 PATH 上的同名文件可能是别人放的（本插件以 root 运行它）。\n   */\n  const arkCli = new ArkCli({ dshHome, logger: ctx.logger, binPath: live().arkcliPath })\n  /** 无浏览器登录的会话管理：谁在登录、授权 URL 是什么、回调喂回去没有。 */\n  const login = new ArkCliLogin({ dshHome, logger: ctx.logger, binPath: live().arkcliPath })\n\n  // --- 缓存 -----------------------------------------------------------------\n  // 这些数据都来自子进程或控制面，轮询时不该每次都重新拉。\n  const CLI_KEY_TTL_MS = 10 * 60_000\n  const CLI_STATE_TTL_MS = 20_000\n  const CLI_STATUS_TTL_MS = 30_000\n  const FAILURE_TTL_MS = 60_000\n  const cliKeyCache = new Map()\n  const cliStateCache = new Map()\n  const planCache = new Map()\n  /** 在途请求：同一个键并发时复用同一个 Promise（见 catalogReport/plan 的注释）。 */\n  const catalogPending = new Map()\n  const planPending = new Map()\n  /** 同一个键的在途请求只跑一次，后来者等同一份结果。 */\n  const inFlight = async (registry, key, run) => {\n    const existing = registry.get(key)\n    if (existing !== undefined) return await existing\n    const promise = Promise.resolve().then(run)\n    registry.set(key, promise)\n    try { return await promise } finally { registry.delete(key) }\n  }\n  /** AK/SK 备选来源的缓存。单独放，别和账户 id 挤在同一个 Map 里。 */\n  let akskCache\n  let cliStatusCache = { at: 0, value: undefined }\n  let catalogCache = { at: 0, value: undefined }\n\n  /**\n   * 账户的 HOME：配置里写了就用写的，否则派生到 `<DSH_HOME>/ark-coding/accounts/<id>`。\n   *\n   * 显式 `home` 必须落在本插件状态根之下，理由：`accounts` 是 volatile（浏览器可写）\n   * 字段，而它的 `home` 会被当成 **root 子进程的 HOME** —— arkcli 随后会在\n   * `<HOME>/.arkcli/` 下写凭据、跑 `auth login`。账户 `id` 有白名单清洗，`home` 却是\n   * 原样透传的，于是一次配置写入就能让 root 往任意目录写文件（`/etc`、`/root/.config`…）。\n   * 运行时从来不需要自定义 HOME —— 多账户隔离靠的就是\"每个账户一个派生目录\"——\n   * 所以越界的值直接拒绝，而不是悄悄接受。\n   */\n  const homeForAccount = (account) => {\n    if (dshHome === undefined) throw new Error(NO_DSH_HOME)\n    if (typeof account.home === 'string' && account.home !== '') {\n      const root = arkcliStateRoot(dshHome)\n      const resolved = resolvePath(account.home)\n      if (resolved === root || resolved.startsWith(`${root}${pathSep}`)) return resolved\n      throw new Error(`${NS}: 账户「${account.id}」的 home 必须位于 ${root} 之下，收到 ${account.home}。`)\n    }\n    return accountHomeDir(dshHome, account.id)\n  }\n\n  /** 按 id 找账户的 HOME（登录时账户可能还没写进配置，所以容忍找不到）。 */\n  const homeForId = (accountId) => {\n    const found = resolveConnection(live()).accounts.find((account) => account.id === accountId)\n    return found === undefined ? homeForAccount({ id: accountId }) : homeForAccount(found)\n  }\n\n  /**\n   * 派生缓存的键。\n   *\n   * **不能只用 `account.id`**：缓存的内容（API key、登录态、额度）取决于这个账户\n   * 指向哪个 HOME / 什么类型 / 哪个凭据引用。用户删掉一个 CLI 账户再用同一个 id 新建\n   * （或者改掉它的 `home`），旧键仍然命中，于是最长 10 分钟里继续拿**旧账户**的 key\n   * 去发请求、额度和登录态也串台 —— 而删掉重建往往正是因为旧账户不该再用了。\n   * 拼上这几个字段后，配置一变键就变，天然失效。id 经过白名单清洗，不含 `|`。\n   */\n  const cacheKeyOf = (account) => [\n    account.id,\n    account.type ?? '',\n    account.home ?? '',\n    account.ref ?? '',\n  ].join('|')\n\n  /** 清掉某个账户的所有派生缓存（登录成功/安装完成后必须调用）。 */\n  const invalidateAccount = (accountId) => {\n    if (accountId === undefined) {\n      cliKeyCache.clear()\n      cliStateCache.clear()\n      planCache.clear()\n      akskCache = undefined\n    } else {\n      // 键是 `${id}|…`，所以按前缀删。\n      const prefix = `${accountId}|`\n      for (const cache of [cliKeyCache, cliStateCache, planCache]) {\n        for (const key of [...cache.keys()]) {\n          if (key === accountId || key.startsWith(prefix)) cache.delete(key)\n        }\n      }\n    }\n    catalogCache = { at: 0, value: undefined }\n  }\n\n  /**\n   * CLI 账户的 API key。\n   *\n   * SSO 登录完之后，arkcli 会把该身份下的 API key 落在自己的 profile 里，\n   * `profile apikey get` 能打印明文。于是 CLI 账户既能查额度/目录，也能直接\n   * 拿来聊天 —— 不需要用户再去控制台手抄一把 key。\n   */\n  const cliKeyOf = async (account) => {\n    const cacheKey = cacheKeyOf(account)\n    const hit = cliKeyCache.get(cacheKey)\n    const now = Date.now()\n    if (hit !== undefined && now - hit.at < CLI_KEY_TTL_MS) return hit.key\n    let key\n    try {\n      const result = await arkCli.profileApiKey({ home: homeForAccount(account) })\n      if (result.ok === true && typeof result.apiKey === 'string') {\n        const parsed = normalizeApiKey(result.apiKey)\n        if (parsed.ok === true) key = parsed.value\n      }\n    } catch { /* 取不到就当未配置，交给账号轮换去处理 */ }\n    cliKeyCache.set(cacheKey, { key, at: now })\n    return key\n  }\n\n  /** CLI 账户的登录态 + 身份（带缓存，避免每个轮询都起两个子进程）。 */\n  const cliStateOf = async (account) => {\n    const cacheKey = cacheKeyOf(account)\n    const hit = cliStateCache.get(cacheKey)\n    const now = Date.now()\n    if (hit !== undefined && now - hit.at < CLI_STATE_TTL_MS) return hit.value\n    let value\n    try {\n      const status = await cliStatus()\n      if (status.installed !== true) {\n        value = { loggedIn: false, needsInstall: true }\n      } else {\n        const home = homeForAccount(account)\n        const auth = await arkCli.authStatus({ home })\n        if (auth.loggedIn !== true) {\n          value = { loggedIn: false }\n        } else {\n          const who = await arkCli.whoami({ home })\n          value = {\n            loggedIn: true,\n            // 凭据的到期时间：决定\"什么时候必须重新登录\"。读不到就是 undefined，\n            // 界面据此只显示\"有时效\"而不编一个日期出来。\n            credentialExpiresAt: readCredentialExpiry(home),\n            identity: {\n              userName: who.userName,\n              userId: who.userId,\n              accountId: who.accountId,\n              isRoot: who.isRoot,\n              authMethod: who.authMethod,\n            },\n          }\n        }\n      }\n    } catch (error) {\n      // 单个账户的状态取不到不该让整份报告挂掉：如实标成未登录并带上原因。\n      value = { loggedIn: false, error: errorText(error) }\n    }\n    cliStateCache.set(cacheKey, { value, at: now })\n    return value\n  }\n\n  const adapter = new ArkCodingAdapter({\n    config: () => config,\n    ctx: () => ctx,\n    marks,\n    logger: ctx.logger,\n    cliKey: cliKeyOf,\n    cliAccountState: cliStateOf,\n    attachments: () => {\n      const attachments = ctx.get('attachments')\n      return attachments === undefined ? undefined : attachments\n    },\n  })\n\n  ctx.llm.registerAdapter([PROVIDER], adapter)\n  ctx.llm.registerConfigurableProviders([\n    { provider: PROVIDER, displayName: DISPLAY_NAME, settingsNs: NS, settingsPath: [] },\n  ])\n  ctx.llm.registerModelDiscovery(NS, createDiscovery())\n\n  /** arkcli 探测结果（带缓存）。 */\n  const cliStatus = async (force = false) => {\n    const now = Date.now()\n    if (!force && cliStatusCache.value !== undefined && now - cliStatusCache.at < CLI_STATUS_TTL_MS) {\n      return cliStatusCache.value\n    }\n    let value\n    try {\n      value = await arkCli.status()\n    } catch (error) {\n      value = { installed: false, error: errorText(error) }\n    }\n    cliStatusCache = { at: now, value }\n    return value\n  }\n\n  /** 找第一个已登录的 CLI 账户的 HOME —— 控制面数据（额度/目录）用它拉。 */\n  const firstLoggedInHome = async (connection) => {\n    for (const account of connection.accounts) {\n      if (account.type !== TYPE_CLI) continue\n      const state = await cliStateOf(account)\n      if (state.loggedIn === true) return homeForAccount(account)\n    }\n    return undefined\n  }\n\n  /**\n   * 官方模型目录。\n   *\n   * 目录是**对照**不是覆盖：内置那 12 行的容量/模态是打 Coding Plan 端点实测的，\n   * 而 arkcli 给的是方舟通用目录的元数据，两者本来就可能有出入。所以这里把官方\n   * 值并排挂上去、把分歧点列出来，让用户看得见，而不是偷偷改掉实测值。\n   */\n  const catalogReport = async (force = false) => {\n    const connection = resolveConnection(live())\n    const now = Date.now()\n    const cached = catalogCache.value\n    if (!force && cached !== undefined) {\n      const ttl = cached.ok === true ? connection.catalogRefreshSeconds * 1000 : FAILURE_TTL_MS\n      if (now - catalogCache.at < ttl) return cached\n    }\n    // 在途去重：缓存只在 await 之后才写，所以并发调用必然全部 miss。设置页按钮连点、\n    // 或者一次 report() 正好撞上手动刷新，会同时起多个 node + arkcli 子进程。\n    // 实测并发 5 次强制刷新 = 5 个子进程。这里让它们共用同一个在途 Promise。\n    return await inFlight(catalogPending, 'catalog', async () => {\n      const empty = (error) => ({\n        ok: false,\n        error,\n        source: undefined,\n        updatedAt: undefined,\n        total: 0,\n        models: MODELS,\n        matched: 0,\n        conflicts: [],\n        unmatchedOfficial: 0,\n        officialSample: [],\n      })\n      const status = await cliStatus()\n      if (status.installed !== true) {\n        const value = empty('还没有可用的 arkcli：先在设置页里点「安装 arkcli」。')\n        catalogCache = { at: Date.now(), value }\n        return value\n      }\n      const home = await firstLoggedInHome(connection)\n      if (home === undefined) {\n        const value = empty('拉取官方模型目录需要一个已登录的 CLI 账户。')\n        catalogCache = { at: Date.now(), value }\n        return value\n      }\n      let result\n      try {\n        result = await arkCli.modelsSearch({ home, size: 0 })\n      } catch (error) {\n        result = { ok: false, items: [], error: errorText(error) }\n      }\n      if (result.ok !== true) {\n        const value = empty(result.error ?? '官方目录拉取失败。')\n        catalogCache = { at: Date.now(), value }\n        return value\n      }\n      const annotated = annotateModels(MODELS, result.items, { updatedAt: result.updatedAt, source: 'arkcli' })\n      const value = {\n        ok: true,\n        error: undefined,\n        source: 'arkcli',\n        updatedAt: result.updatedAt,\n        total: result.items.length,\n        ...annotated,\n      }\n      catalogCache = { at: Date.now(), value }\n      return value\n    })\n  }\n\n  /**\n   * 组装一次用量报告。\n   *\n   * 真实套餐额度（plan）优先走 arkcli：每个已登录的 CLI 账户各查一次，谁有\n   * 数据谁上。AK/SK 只作为备选（没有 CLI 账户、或 CLI 账户都没登录时）。\n   * 两条路都拿不到就如实说明原因（分三种：没账户 / 有 CLI 账户但没登录 /\n   * 只有 API Key）—— **不再回落到本机统计**：本机 token 数不是套餐额度，\n   * 摆在一起只会让人误读成\"还剩这么多\"。\n   */\n  const report = async () => {\n    const connection = resolveConnection(live())\n    const accounts = await adapter.accountStates()\n\n    // --- 每个 CLI 账户各自的真实额度 ---\n    const planAccounts = []\n    /** 至少有一个 CLI 账户真的登录了（不是\"配了 CLI 账户\"）。 */\n    let cliLoggedIn = false\n    for (const account of connection.accounts) {\n      if (account.type !== TYPE_CLI) continue\n      const state = await cliStateOf(account)\n      if (state.loggedIn !== true) {\n        planAccounts.push({\n          accountId: account.id,\n          label: account.label,\n          ok: false,\n          windows: [],\n          error: state.needsInstall === true ? '还没有安装 arkcli。' : '这个账户尚未登录。',\n        })\n        continue\n      }\n      cliLoggedIn = true\n      const ttl = connection.usageRefreshSeconds * 1000\n      const cacheKey = cacheKeyOf(account)\n      const hit = planCache.get(cacheKey)\n      let plan\n      if (hit !== undefined && Date.now() - hit.at < ttl) {\n        plan = hit.value\n      } else {\n        // 在途去重（同上）：控制面超时 120s，而客户端轮询是 fire-and-forget，\n        // 慢的时候会叠起多个 `arkcli usage plan` 子进程。\n        plan = await inFlight(planPending, cacheKey, async () => {\n          let fetched\n          try {\n            fetched = await arkCli.usagePlan({ home: homeForAccount(account) })\n          } catch (error) {\n            fetched = { ok: false, error: errorText(error) }\n          }\n          const value = fetched.ok === true\n            ? { ok: true, items: fetched.items, viewer: fetched.viewer, error: undefined }\n            : { ok: false, items: [], error: fetched.error ?? '额度查询失败。' }\n          planCache.set(cacheKey, { at: Date.now(), value })\n          return value\n        })\n      }\n      if (plan.ok !== true) {\n        planAccounts.push({ accountId: account.id, label: account.label, ok: false, windows: [], error: plan.error })\n        continue\n      }\n      const shaped = windowsFromItems(plan.items)\n      planAccounts.push({\n        accountId: account.id,\n        label: account.label,\n        ok: shaped.windows.length > 0,\n        windows: shaped.windows,\n        error: shaped.error,\n        tier: shaped.tier,\n        updatedAt: shaped.updatedAt,\n        viewer: plan.viewer,\n      })\n    }\n\n    // --- AK/SK 备选：只在没有任何 CLI 账户给出数据时才去试 ---\n    let akskEntry\n    const anyCliOk = planAccounts.some((entry) => entry.ok === true)\n    if (!anyCliOk && connection.accessKeyId !== '') {\n      const cachedFor = `${connection.accessKeyId}|${connection.secretAccessKeyEnv}|${connection.region}`\n      const ttl = connection.usageRefreshSeconds * 1000\n      if (akskCache !== undefined && akskCache.key === cachedFor && Date.now() - akskCache.at < ttl) {\n        akskEntry = akskCache.value\n      } else if (akskCache !== undefined && akskCache.key === cachedFor && akskCache.value.ok !== true && Date.now() - akskCache.at < FAILURE_TTL_MS) {\n        akskEntry = akskCache.value\n      } else {\n        akskEntry = await (async () => {\n          const base = { accountId: '__aksk__', label: 'AK/SK', source: 'aksk' }\n          let secret\n          try {\n            secret = await adapter.resolveRef(connection.secretAccessKeyEnv, undefined)\n          } catch (error) {\n            return { ...base, ok: false, windows: [], error: `Secret AccessKey 不可用：${errorText(error)}` }\n          }\n          if (secret === undefined) {\n            return { ...base, ok: false, windows: [], error: `未配置 Secret AccessKey（凭据引用 ${connection.secretAccessKeyEnv}）。` }\n          }\n          try {\n            const usage = await fetchCodingPlanUsage({\n              accessKeyId: connection.accessKeyId,\n              secretAccessKey: secret,\n              region: connection.region,\n            })\n            if (usage.windows.length === 0) {\n              return { ...base, ok: false, windows: [], error: '控制面没有返回任何额度窗口。' }\n            }\n            return { ...base, ok: true, windows: usage.windows, updatedAt: usage.updatedAt }\n          } catch (error) {\n            return { ...base, ok: false, windows: [], error: errorText(error) }\n          }\n        })()\n        akskCache = { at: Date.now(), key: cachedFor, value: akskEntry }\n      }\n    }\n\n    const allPlanEntries = akskEntry === undefined ? planAccounts : [...planAccounts, akskEntry]\n    const firstOk = allPlanEntries.find((entry) => entry.ok === true)\n\n    // --- 侧边栏卡片该不该显示（`sidebarQuota: auto` 的判据） --------------------\n    // 「有绑定」= 已登录的 CLI 账户，或一对填全了的 AK/SK。判据刻意**不看这一次\n    // 拉取成不成功**：登录已经完成、AK/SK 已经填好，那就该显示卡片；控制面抖一下\n    // 或者网断一下，不该让卡片自己闪没。\n    const akskBound = cliLoggedIn || connection.accessKeyId === ''\n      ? false\n      : await (async () => {\n        try {\n          return (await adapter.resolveRef(connection.secretAccessKeyEnv, undefined)) !== undefined\n        } catch {\n          return false\n        }\n      })()\n    const usageCapable = cliLoggedIn || akskBound\n    const sidebarQuota = sidebarQuotaState(connection.sidebarQuota, usageCapable)\n\n    const cliAccountsExist = connection.accounts.some((account) => account.type === TYPE_CLI)\n    // 三类\"查不到额度\"的原因要分开说，否则用户不知道该动哪里：\n    //   · 一个账户都没有 → 去建账户；\n    //   · 有 CLI 账户但没登录 → 去登录；\n    //   · 只有 API Key 账户 → 说清楚 API Key 天生查不到，要么加 CLI 账户，要么填 AK/SK。\n    const accountsExist = connection.accounts.length > 0\n    const plan = firstOk === undefined\n      ? {\n        ok: false,\n        source: undefined,\n        windows: [],\n        accounts: allPlanEntries,\n        error: allPlanEntries.find((entry) => typeof entry.error === 'string' && entry.error !== '')?.error\n          ?? (cliAccountsExist\n            ? 'CLI 账户还没有登录。'\n            : (accountsExist\n              ? 'API Key 只能聊天，查不到套餐额度：额度在控制面，只认 SSO 身份（或一对 AK/SK）。想要百分比就再加一个「CLI 登录」的账户，或填下面的 AK/SK。'\n              : '还没有任何账户：点上面的「添加账户」建一个。「CLI 登录」能给真实额度，「API Key」只能聊天。')),\n      }\n      : {\n        ok: true,\n        source: firstOk.source ?? 'arkcli',\n        windows: firstOk.windows,\n        updatedAt: firstOk.updatedAt,\n        accounts: allPlanEntries,\n        error: undefined,\n      }\n\n    const catalog = await catalogReport()\n    const cli = await cliStatus()\n\n    return {\n      provider: PROVIDER,\n      displayName: DISPLAY_NAME,\n      accounts,\n      plan,\n      catalog,\n      cli: {\n        installed: cli.installed === true,\n        path: cli.path,\n        version: cli.version,\n        source: cli.source,\n        error: cli.error,\n      },\n      activeAccount: connection.activeAccount,\n      sidebarQuota,\n      refreshSeconds: connection.usageRefreshSeconds,\n      reportedAt: Date.now(),\n    }\n  }\n\n  /** 登录成功后统一收尾：清缓存 + 拿身份。 */\n  const finishLogin = async (accountId) => {\n    invalidateAccount(accountId)\n    let identity\n    try {\n      const who = await arkCli.whoami({ home: homeForId(accountId) })\n      identity = {\n        userName: who.userName,\n        userId: who.userId,\n        accountId: who.accountId,\n        isRoot: who.isRoot,\n        authMethod: who.authMethod,\n      }\n    } catch { /* 身份拿不到不算登录失败 */ }\n    return identity\n  }\n\n  const accountIdOf = (input) => (typeof input.accountId === 'string' ? input.accountId.trim() : '')\n\n  const deps = {\n    report,\n\n    async cliStatus() {\n      const status = await cliStatus(true)\n      return {\n        ok: status.installed === true,\n        installed: status.installed === true,\n        path: status.path,\n        version: status.version,\n        source: status.source,\n        error: status.error,\n      }\n    },\n\n    async cliInstall() {\n      let result\n      try {\n        result = await arkCli.install()\n      } catch (error) {\n        return { ok: false, error: errorText(error) }\n      }\n      invalidateAccount(undefined)\n      cliStatusCache = { at: 0, value: undefined }\n      const status = await cliStatus(true)\n      return {\n        ok: result.ok === true && status.installed === true,\n        path: status.path ?? result.path,\n        version: status.version ?? result.version,\n        installed: status.installed === true,\n        error: result.ok === true && status.installed !== true\n          ? (status.error ?? '安装完成但 arkcli 无法执行。')\n          : result.error,\n      }\n    },\n\n    async catalogRefresh() {\n      const value = await catalogReport(true)\n      return value\n    },\n\n    async loginBegin(input) {\n      const accountId = accountIdOf(input)\n      if (accountId === '') return { ok: false, error: '缺少账户 id。' }\n      const home = homeForId(accountId)\n      // 同一个账户重复点「登录」时，先把上一条会话收掉，免得留下孤儿进程。\n      try { await login.cancel({ ref: accountId }) } catch { /* 没有旧会话就无所谓 */ }\n      const started = await login.start({ home, ref: accountId })\n      if (started.ok !== true) {\n        return { ok: false, accountId, error: started.error }\n      }\n      return {\n        ok: true,\n        accountId,\n        url: started.url,\n        port: started.port,\n        error: undefined,\n        // 这里**不再返回一段写死的说明文字**：客户端已经有等价且双语的\n        // `loginFerryNote` / `loginOrWait`（它才是负责本地化的那一侧）。宿主返回中文\n        // 只会在英文界面里夹一整天中文，所以只回一个机器可读的标记。\n        notice: 'copyCallbackUrl',\n      }\n    },\n\n    async loginPoll(input) {\n      const accountId = accountIdOf(input)\n      if (accountId === '') return { ok: false, error: '缺少账户 id。' }\n      const polled = login.poll({ ref: accountId })\n      if (polled.state === 'unknown') {\n        return { ok: false, accountId, state: 'unknown', error: '登录会话不存在（可能已取消或插件重启过）。' }\n      }\n      if (polled.state === 'done') {\n        const identity = await finishLogin(accountId)\n        return { ok: true, accountId, state: 'done', identity, error: undefined }\n      }\n      return {\n        ok: polled.ok !== false,\n        accountId,\n        state: polled.state,\n        url: polled.url,\n        error: polled.error,\n      }\n    },\n\n    async loginSubmit(input) {\n      const accountId = accountIdOf(input)\n      if (accountId === '') return { ok: false, error: '缺少账户 id。' }\n      const raw = typeof input.input === 'string' ? input.input : ''\n      let submitted\n      try {\n        submitted = await login.submit({ ref: accountId, input: raw })\n      } catch (error) {\n        return { ok: false, accountId, state: 'error', error: errorText(error) }\n      }\n      if (submitted.state === 'done') {\n        const identity = await finishLogin(accountId)\n        return { ok: true, accountId, state: 'done', identity, error: undefined }\n      }\n      return {\n        ok: submitted.ok === true,\n        accountId,\n        state: submitted.state,\n        note: submitted.note,\n        error: submitted.error,\n      }\n    },\n\n    async loginCancel(input) {\n      const accountId = accountIdOf(input)\n      if (accountId === '') return { ok: false, error: '缺少账户 id。' }\n      try {\n        const cancelled = await login.cancel({ ref: accountId })\n        return { ok: true, cancelled: cancelled?.killed === true, accountId }\n      } catch (error) {\n        return { ok: false, accountId, error: errorText(error) }\n      }\n    },\n  }\n\n  ctx.inject(['typert'], (remoteCtx) => {\n    new ArkCodingUsageService(remoteCtx, deps)\n    const registry = remoteCtx.typert\n    const unregister = registry.register({\n      package: REMOTE_PACKAGE,\n      face: 'host',\n      schemas: [],\n      // 手写 Remote 没有生成的反射模型，用官方的\"空模型\"形状，\n      // 而不是留一个 undefined 给注册表检查。\n      model: { services: [], events: [], objects: [] },\n      invocations: [\n        USAGE_REPORT_DESCRIPTOR,\n        CLI_STATUS_DESCRIPTOR,\n        CLI_INSTALL_DESCRIPTOR,\n        CATALOG_REFRESH_DESCRIPTOR,\n        LOGIN_BEGIN_DESCRIPTOR,\n        LOGIN_POLL_DESCRIPTOR,\n        LOGIN_SUBMIT_DESCRIPTOR,\n        LOGIN_CANCEL_DESCRIPTOR,\n      ],\n    })\n    remoteCtx.effect(() => () => void unregister(), `${NS}: usage remote`)\n  })\n\n  // 插件卸载时把还挂着的登录子进程收掉，别留孤儿。\n  // 用可选调用：精简的测试 ctx 上没有 effect，而\"收尾\"这件事不该让插件挂不起来。\n  if (typeof ctx.effect === 'function') {\n    ctx.effect(() => () => {\n      try { login.disposeAll() } catch { /* 卸载阶段尽力而为 */ }\n    }, `${NS}: arkcli login sessions`)\n  }\n\n  ctx.logger?.info?.(`${NS}: 已注册 ${MODELS.length} 个火山方舟 Coding Plan 模型（路由 ${PROVIDER}）`)\n}\n\nexport {\n  MODELS,\n  modelById,\n  withoutUndefined,\n  toModelInfo,\n  toResolvedModelInfo,\n  contextWindowOf,\n  modelIsVisible,\n  resolveConnection,\n  unwrapVolatileConfig,\n}\n"
