    {
      "path": "accounts.js",
      "content": "/**\n * 多账户池与轮换标记。\n *\n * 火山方舟 Coding Plan 的额度是**按账号**算的：一个账号的 5 小时窗口打满，\n * 换另一个账号的 key 就还能继续。所以适配器在发请求前按顺序解析可用账号，\n * 遇到「这个账号被限流/额度用尽/鉴权失败」就在**还没吐出任何内容之前**换下一个。\n *\n * 账户有两种来源，靠 `type` 区分：\n *\n * - `apikey`：用户直接粘一把方舟 API Key。它能打数据面（`/api/coding/v3`），\n *   但控制面（套餐额度、官方模型目录）不认 API Key —— 那两样只有 SSO 身份能查。\n * - `cli`：用户在设置页走 arkcli 的 SSO 登录。登录后在每个账户**独立的 HOME**\n *   下存一份 arkcli 身份，于是同一个进程里可以同时持有多个账号，互不打架\n *   （arkcli 的状态目录写死在 `$HOME/.arkcli`，没有环境变量可以改，所以隔离\n *   只能靠换 HOME）。这种账户既能取到 key 用于聊天，也能查套餐额度和模型目录。\n *\n * 标记（mark）是进程内的短时记忆：命中限流后让这个账号冷却一段时间，\n * 免得每个请求都先撞一次墙。冷却到期自动恢复，不需要用户做任何事。\n *\n * 这个模块刻意不依赖 cordis，也刻意不依赖 arkcli：账号由调用方解析好再传进来，\n * 标记只用一个 Map。`home` 为空表示\"用默认位置\"，具体路径由调用方决定。\n *\n * 末尾的 `sidebarQuotaState` 也是纯函数：它把\"有没有能查额度的账户\"翻译成\n * \"左下角那张卡片该不该显示\"。放在这里是因为判据的输入就是账户类型。\n *\n * @module dsh-ark-coding-provider/accounts\n */\n\n/** 账户类型：用户手填的 API Key。 */\nexport const TYPE_API_KEY = 'apikey'\n/** 账户类型：arkcli SSO 登录（带独立 HOME）。 */\nexport const TYPE_CLI = 'cli'\n/** 允许出现在配置里的账户类型。 */\nexport const ACCOUNT_TYPES = [TYPE_API_KEY, TYPE_CLI]\n\n/** 配置里单个账户 id 允许出现的字符；其余一律换成 `_`。 */\nconst ID_SAFE = /[^A-Za-z0-9._-]/g\n\n/**\n * 归一化账户 id。\n *\n * **全仓库唯一实现**（`arkcli.js` 直接 re-export 这一份）。以前 `accounts.js` 与\n * `arkcli.js` 各写了一份，规则还不一样：一个截断到 64 字符、空值回退 `account`，\n * 另一个不截断、回退 `default`。于是一个超过 64 字符的手写 id，会得到两个不同的\n * HOME —— 登录写在 A、聊天去 B 找 key，表现为\"登录成功了但一直说没登录\"。\n * alias 的两条路径必须落在同一个目录上，所以只留一份。\n *\n * 账户 id 会参与两个危险的地方：一是 CLI 账户的 HOME 目录名，二是设置页的键。\n * 所以这里只放行 `[A-Za-z0-9._-]`，并且干掉前导点 —— `../` 这类输入必须\n * 变成一个普通目录名，而不是逃出账户根目录。\n *\n * @param raw - 任意账户 id（可能含中文、斜杠、超长、空值）。\n * @param fallback - 清洗后为空时用的名字。\n */\nexport function sanitizeAccountId(raw, fallback = 'default') {\n  const text = typeof raw === 'string' ? raw.trim() : ''\n  const cleaned = text.replace(ID_SAFE, '_').replace(/^\\.+/, '').slice(0, 64)\n  return cleaned === '' ? fallback : cleaned\n}\n\n/** 账户类型归一化：认不出来的按 apikey 处理（旧配置没有 type 字段）。 */\nexport function normalizeAccountType(raw) {\n  return raw === TYPE_CLI ? TYPE_CLI : TYPE_API_KEY\n}\n\n/** 一个账户的显示名：用户填了就用用户的，否则给一个能区分开的名字。 */\nexport function defaultAccountLabel(account, index) {\n  if (account.type === TYPE_CLI) return `CLI 账户 ${index + 1}`\n  return `API Key 账户 ${index + 1}`\n}\n\n/** 默认冷却时长：命中限流/额度后先躲 5 分钟（参考同类实现的量级）。 */\nexport const DEFAULT_COOLDOWN_MS = 5 * 60_000\n/** 鉴权失败（key 错/被禁）的冷却更长：它不会自己好，但也不该永久封死。 */\nexport const AUTH_COOLDOWN_MS = 30 * 60_000\n\n/**\n * 把配置里的账户列表归一化成统一形状。\n *\n * **主要来源是配置里的 `accounts` 数组。** 另外有一条**兜底**：当 `accounts` 为空时，\n * 顶层 `apiKeyEnv`/`apiKey` 会被当成一个 id 为 `default` 的 API Key 账户。\n *\n * 为什么必须有这条兜底（2026-10-16 补回）：官方 Models 页给每个可配置 provider 都渲染\n * 一个密钥编辑器，它的目标 ref 是**从 provider 名推出来的**（`ark-coding` →\n * `ARK_CODING_API_KEY`），插件管不着。如果插件不读顶层字段，用户在官方卡片里粘了 key、\n * 界面显示\"已配置\"，聊天却报\"一个可用账户都没有\" —— 同一屏两张卡片互相打脸，\n * 而这是新用户第一条会踩的路。只在一个账户都没有时启用，所以多账户用户完全不受影响；\n * 把 `apiKeyEnv` 显式设成空串就等于关掉这条兜底。\n *\n * 返回的每个账户：\n *\n * - `id`：稳定标识，写入配置；CLI 账户的 HOME 目录名由它派生。\n * - `label`：显示名。用户没填就按类型给个序号名。\n * - `type`：`apikey` / `cli`。\n * - `ref`：凭据服务引用（只有 apikey 用得上）。\n * - `literal`：组合配置里直接写的密钥（只有 apikey 用得上）。\n * - `home`：CLI 账户的显式 HOME；为空表示\"交给调用方按 id 派生\"。\n *\n * @param config - 插件配置（已解 volatile 包装）。\n * @param fallbackRef - 兜底账户用的凭据引用名；空/非法时不出兜底账户。\n */\nexport function describeAccounts(config, fallbackRef) {\n  const list = Array.isArray(config.accounts)\n    ? config.accounts.filter((entry) => typeof entry === 'object' && entry !== null)\n    : []\n\n  const mapped = list.map((entry, position) => {\n    const type = normalizeAccountType(entry.type)\n    const id = sanitizeAccountId(entry.id, `account-${position + 1}`)\n    const ref = type === TYPE_API_KEY\n      ? (typeof entry.apiKeyEnv === 'string' && entry.apiKeyEnv !== ''\n        ? entry.apiKeyEnv\n        : `ARK_CODING_API_KEY_${position + 1}`)\n      : ''\n    const literal = type === TYPE_API_KEY && typeof entry.apiKey === 'string' && entry.apiKey.trim() !== ''\n      ? entry.apiKey.trim()\n      : undefined\n    const label = typeof entry.label === 'string' && entry.label.trim() !== '' ? entry.label.trim() : ''\n    const home = type === TYPE_CLI && typeof entry.home === 'string' && entry.home.trim() !== '' ? entry.home.trim() : undefined\n    return {\n      id,\n      label: label === '' ? defaultAccountLabel({ type }, position) : label,\n      labelIsCustom: label !== '',\n      type,\n      ref,\n      literal,\n      home,\n    }\n  })\n\n  // 同一个 id 出现两次，两个账户就会共用同一个 HOME 与同一组派生缓存（额度/登录态\n  // 串台、冷却互相影响）。手改配置很容易撞上，所以保留第一个、丢掉后来者。\n  const seen = new Set()\n  const accounts = []\n  for (const account of mapped) {\n    if (seen.has(account.id)) continue\n    seen.add(account.id)\n    accounts.push(account)\n  }\n\n  if (accounts.length === 0 && typeof fallbackRef === 'string' && fallbackRef !== '') {\n    accounts.push({\n      id: 'default',\n      label: '默认账户',\n      labelIsCustom: false,\n      type: TYPE_API_KEY,\n      ref: fallbackRef,\n      literal: typeof config.apiKey === 'string' && config.apiKey.trim() !== '' ? config.apiKey.trim() : undefined,\n      home: undefined,\n    })\n  }\n  return accounts\n}\n\n/** 进程内的账号标记表：谁在冷却、为什么、到什么时候。 */\nexport class AccountMarks {\n  constructor(now = () => Date.now()) {\n    this.now = now\n    /** @type {Map<string, {reason: string, until: number, at: number}>} */\n    this.marks = new Map()\n  }\n\n  /** 记一个标记。`until` 是绝对时间戳。 */\n  mark(id, reason, until) {\n    this.marks.set(id, { reason, until, at: this.now() })\n  }\n\n  /** 清除一个标记（这个账号刚刚成功了）。 */\n  clear(id) {\n    this.marks.delete(id)\n  }\n\n  /** 这个账号现在可不可用。 */\n  usable(id) {\n    const mark = this.marks.get(id)\n    if (mark === undefined) return true\n    if (mark.until <= this.now()) {\n      this.marks.delete(id)\n      return true\n    }\n    return false\n  }\n\n  /** 面向设置页的标记快照（只读）。 */\n  snapshot() {\n    const out = {}\n    for (const [id, mark] of this.marks) {\n      if (mark.until <= this.now()) continue\n      out[id] = { reason: mark.reason, until: mark.until, at: mark.at }\n    }\n    return out\n  }\n}\n\n/**\n * 把失败归类成「要不要换账号」。\n *\n * - `AUTH`：这个 key 本身不可用（错、被禁、不属于本套餐）→ 换。\n * - `RATE_LIMIT` / `QUOTA`：这个账号的窗口打满了 → 换。\n * - 其余（上下文超限、内容不合规、参数错）换账号也没用，原样抛出去。\n *\n * @param code - DSH 的稳定失败码。\n * @returns 换账号的原因，或 undefined 表示不该换。\n */\nexport function rotationReasonFor(code) {\n  if (code === 'AUTH' || code === 'INVALID_CREDENTIAL') return 'invalid-credential'\n  if (code === 'RATE_LIMIT') return 'rate-limit'\n  if (code === 'QUOTA' || code === 'ACCOUNT_QUOTA') return 'quota'\n  return undefined\n}\n\n/** 一个原因对应的冷却时长。 */\nexport function cooldownFor(reason) {\n  return reason === 'invalid-credential' ? AUTH_COOLDOWN_MS : DEFAULT_COOLDOWN_MS\n}\n\n/**\n * 排一次请求的账号顺序。\n *\n * 顺序：明确指定的账号 → 其余账号。冷却中的账号排到最后（而不是直接剔除），\n * 这样「所有账号都在冷却」时仍会尝试，而不是直接报「没有可用账号」。\n *\n * @param accounts - 已解析的账号（含 key）。\n * @param marks - 标记表。\n * @param preferredId - 配置里指定的当前账号 id，可选。\n * @returns 有序的可用账号。\n */\nexport function orderAccounts(accounts, marks, preferredId) {\n  const usable = accounts.filter((account) => account.key !== undefined)\n  const rank = (account) => {\n    if (account.id === preferredId) return 0\n    if (marks.usable(account.id)) return 1\n    return 2\n  }\n  return [...usable].sort((left, right) => rank(left) - rank(right))\n}\n\n/** 从错误里取 ProviderRetryAfter（毫秒），用于把冷却调到服务端要求的时长。 */\nexport function retryAfterMsOf(failure) {\n  const value = failure?.providerRetryAfterMs\n  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : undefined\n}\n\n/**\n * 解析 `sidebarQuota` 的三态。\n *\n * - `auto`（默认）：有能查到套餐额度的绑定（已登录的 CLI 账户，或一对填全的\n *   AK/SK）就显示卡片；两者都没有就不显示 —— 一张永远只写着\"未配置\"的常驻\n *   卡片没有信息量。\n * - `on` / `off`：用户在设置页里显式选的档位，永远压过自动判据。\n *\n * 单独成纯函数是为了能被离线测试钉死：这条规则决定卡片显示不显示，\n * 藏在 report 闭包里就只能靠真机去看。\n *\n * @param mode - 配置里的档位；无法识别时按 `auto`。\n * @param capable - 是否真的存在能查额度的绑定。\n */\nexport function sidebarQuotaState(mode, capable) {\n  const normalized = mode === 'on' |