      "content": "/**\n * arkcli：官方 ARK CLI（`@volcengine/ark-cli`）的进程封装。\n *\n * ## 为什么要包一层外部进程\n *\n * 用户「扫码 / SSO 登录火山方舟」这件事没有公开 HTTP 接口，只有官方 CLI 会做。\n * 而 CLI 自带的是**控制面**能力：`auth status|whoami|login`、`usage plan`、\n * `models search`、`profile apikey get` —— 正好覆盖「按账号看真实套餐额度」与\n * 「把登录结果换成一把可用的 API key」这两件事。所以这里不重造协议，只封装进程。\n *\n * ## 为什么每个账号一个 HOME（而不是环境变量）\n *\n * arkcli 把自己的状态放在 `os.UserHomeDir()/.arkcli`，并且**没有任何环境变量可以\n * 覆盖**（没有 ARKCLI_HOME / ARK_HOME / XDG 之类）。实测：`HOME=/tmp/h1 arkcli auth\n * status` 用 `/tmp/h1/.arkcli`，与 `/tmp/h2/.arkcli` 完全独立。因此多账号隔离的\n * 唯一可靠做法就是**给子进程换 HOME**：账号 id 只经过白名单字符清洗后就变成目录名。\n *\n * ## 为什么子进程要一份\"最小环境\"\n *\n * 如果直接继承父进程环境，宿主自己的 `ARK_API_KEY` / `ARK_PROFILE` / `ARK_BASE_URL`\n * / `VOLC_*` 会被 arkcli 当成\"当前账号\"读走：那样我们以为在查 A 账号，实际查的是\n * 宿主自己的账号，既串了数据也可能把宿主的凭据写进别的账号目录。所以子进程环境是\n * 白名单重建的，只有 PATH/HOME/LANG/LC_ALL/TMPDIR 与几个明确的 ARKCLI_* 开关。\n *\n * ## 为什么登录要\"把回调 URL 转回环地址\"\n *\n * `arkcli auth login --no-browser` 的实测行为（1.0.39）：在 **stderr** 打印一行提示\n * 加一行授权 URL（URL 里带 `callbackPort`），然后在 **127.0.0.1:<callbackPort>** 上\n * 起一个 HTTP 监听并**一直等**。它不读 stdin、不写 `.sso-pending.json`、也没有\n * `--code` 兑换（包内文档描述的两段式流程在这个构建里并不存在）。\n *\n * 用户在任意设备上打开授权 URL，SSO 完成后浏览器会被重定向到\n * `http://127.0.0.1:<port>/arkcli/broker/callback?...`。因为 DSH 服务端在远端，\n * 这次跳转在用户机器上必然失败，但**回调 URL 留在浏览器地址栏里**。用户把它粘回\n * 设置页，我们就在宿主机上把这条 GET 转发给回环监听，登录随即完成、子进程退出。\n *\n * 转发时 Host 头必须是 `127.0.0.1:<port>` —— 这是**实测**出来的，不是猜的：回环\n * 监听会校验 Host，`localhost:<port>`、裸 `127.0.0.1`、`[::1]:<port>`、端口差一个\n * 数字，全部被判 `invalid host`。详见 `submit()` 里的说明。\n *\n * 这就是本模块 `ArkCliLogin` 的全部职责：start（拿 URL）→ 用户操作 → submit（转发）。\n * 之所以不提供 `--code` 路径：那条路在这个构建里只会回「没有待完成的登录会话」，\n * 我们把它转成一句明确的提示，让用户改粘 URL。\n *\n * 转发那条 GET 用的是 `node:http` 而不是全局 fetch：Fetch 规范和 undici 会把 `Host`\n * 当 forbidden header 丢掉，而回环监听会校验它（详见 `createHttpFetch` 的说明）。\n *\n * 本模块是纯的：不 import cordis，不读全局配置，所有外部依赖（spawn / fetch / now）\n * 都可注入，因此可以离线单测。\n *\n * @module dsh-ark-coding-provider/arkcli\n */\n\nimport { spawn as nodeSpawn } from 'node:child_process'\nimport { randomBytes } from 'node:crypto'\nimport { existsSync, mkdirSync, readFileSync } from 'node:fs'\nimport { request as httpRequest } from 'node:http'\nimport { tmpdir } from 'node:os'\nimport { delimiter, join } from 'node:path'\n// 账号 id 的清洗**只保留 accounts.js 那一份实现**：它在 accounts.js 里决定\"聊天用哪个\n// HOME\"，在这里决定\"登录写到哪个 HOME\"，两处必须完全一致，否则超长 id 会分裂成两个目录。\nimport { sanitizeAccountId } from './accounts.js'\n\n/** 官方 CLI 的 npm 包名。 */\nexport const ARKCLI_PACKAGE = '@volcengine/ark-cli'\n/** SSO 回调路由。实测：其它路径 404，缺参数 400。 */\nexport const CALLBACK_PATH = '/arkcli/broker/callback'\n/**\n * 安装时用的版本。\n *\n * **钉版本，不装 `latest`**：额度、官方目录、聊天用的 API key 三条链全都建立在\n * arkcli 的输出形状上（`usage plan --format json`、`models search`、\n * `profile apikey get`），而它的容错解析会让\"字段改名\"表现成\"查不到额度\"而不是\n * 明确报错。上游已经咬过一次（1.0.16 起关掉了 AK/SK 登录通道，见本文件另一处注释）。\n * 装 `latest` 等于每次点安装都绑定当天的最新版，且用户毫不知情。\n * 1.0.39 是本插件实测通过、并且当前这台机器正在用的版本。\n */\nconst DEFAULT_INSTALL_VERSION = '1.0.39'\n/** 普通子命令默认超时。 */\nconst DEFAULT_RUN_TIMEOUT_MS = 60_000\n/** 控制面查询（usage plan / models search）默认超时。 */\nconst DEFAULT_CONTROL_PLANE_TIMEOUT_MS = 120_000\n/** 安装默认超时：实测一次完整安装（含 postinstall 下载 Go 二进制）约 12 秒。 */\nconst INSTALL_TIMEOUT_MS = 300_000\n/** 登录会话最长存活时间。 */\nconst LOGIN_TTL_MS = 10 * 60_000\n/** 等授权链接出现的超时。 */\nconst LOGIN_START_TIMEOUT_MS = 30_000\n/** 转发回调后等子进程退出的超时。 */\nconst LOGIN_WAIT_TIMEOUT_MS = 20_000\n/** 安装 npm 时用的固定参数（安静、不审计、不写 funding 提示）。 */\nconst NPM_INSTALL_FLAGS = ['--no-audit', '--no-fund', '--loglevel=error']\n/**\n * 单个子进程 stdout/stderr 的累积上限（字符）。\n *\n * 正常输出远小于这个数；但异常冗长的报错、日志疯跑、或者失控的子进程不该把\n * 宿主内存吃光。到达上限后停止累积（仍继续把流读干净，避免管道写满把子进程卡住）。\n */\nconst MAX_CHILD_OUTPUT_CHARS = 1_000_000\n\n// ---------------------------------------------------------------------------\n// 路径\n// ---------------------------------------------------------------------------\n\n/** 本插件的状态根：`<dshHome>/ark-coding`。 */\nexport function arkcliStateRoot(dshHome) {\n  return join(dshHome, 'ark-coding')\n}\n\n/** 托管安装目录：`<dshHome>/ark-coding/cli`。 */\nexport function managedInstallDir(dshHome) {\n  return join(arkcliStateRoot(dshHome), 'cli')\n}\n\n/** 托管安装后的可执行文件：`<installDir>/node_modules/.bin/arkcli`。 */\nexport function managedBinPath(dshHome) {\n  return join(managedInstallDir(dshHome), 'node_modules', '.bin', 'arkcli')\n}\n\n/** 无状态子命令（`--version`、安装）用的中性 HOME，避免往用户的 `~/.arkcli` 里写东西。 */\nexport function neutralHomeDir(dshHome) {\n  return join(arkcliStateRoot(dshHome), 'neutral')\n}\n\n/**\n * 清洗账号 id，使它一定能安全地当目录名。\n *\n * **实现只有一份**，在 `accounts.js` 里：`accounts.js` 用它推导\"聊天用哪个 HOME\"，\n * 本模块用它推导\"登录写到哪个 HOME\"，两处必须是同一个函数，否则超长 id 会让\n * 登录与聊天落在两个目录（表现成\"登录成功了却一直说没登录\"）。\n */\nexport { sanitizeAccountId }\n\n/** 某个账号的 HOME：`<dshHome>/ark-coding/accounts/<sanitized id>`。 */\nexport function accountHomeDir(dshHome, accountId) {\n  return join(arkcliStateRoot(dshHome), 'accounts', sanitizeAccountId(accountId))\n}\n\n/**\n * 读 CLI 账户凭据的**到期时间**（epoch ms）；读不到就返回 `undefined`。\n *\n * 为什么要专门读文件：`auth status` 里的 `control_plane_auth.sts_expires_at_ms` 是\n * STS 的 15 分钟到期（arkcli 自己会刷新），对用户毫无意义 —— 它永远\"还有 15 分钟\"。\n * 真正决定**什么时候必须重新登录**的是 profile 上的 `expires_at`（单位秒），它落在\n * `<HOME>/.arkcli/config.yaml` 里。\n *\n * 实测：一个 2026-10-16 登录的 Coding Plan 账户给出 `expires_at = 1797350399`，\n * 也就是 **2026-12-15 23:59:59（UTC+8）**。这是个会随租户/策略变化的服务端事实，\n * 所以界面**显示算出来的具体日期**，而不是写死一句\"每 N 天要重登\"。\n *\n * 解析用逐行扫描而不是引一个 YAML 库：只需要 `default_profile` 那一段里的一个数字，\n * 为此拉进一个依赖不划算。优先取 default profile 的；找不到就退回全文件里最早的那个\n * （最早到期的最该被提醒）。\n *\n * @param home - 账户的 HOME。\n * @param readFile - 可注入的读取器（测试用）。\n * @returns epoch 毫秒，或 `undefined`。\n */\nexport function readCredentialExpiry(home, readFile = readFileSync) {\n  if (typeof home !== 'string' || home === '') return undefined\n  let text\n  try { text = readFile(join(home, '.arkcli', 'config.yaml'), 'utf8') } catch { return undefined }\n  if (typeof text !== 'string' || text === '') return undefined\n\n  const wanted = /^\\s*default_profile:\\s*(\\S+)\\s*$/m.exec(text)?.[1]\n  const sectionOf = (line) => /^(\\s*)(\\S.*?):\\s*$/.exec(line)\n  const expiryOf = (line) => /^\\s*expires_at:\\s*(-?\\d+)\\s*$/.exec(line)\n  const lines = text.split('\\n')\n\n  // 优先在**目标 profile 自己的缩进块**里找。\n  // 旧实现一看到任意 `  key:` 形态的行就把 depth 重置成 -1，于是 profile 内部的嵌套\n  // map（`keystore:`、`cache:` 之类）会把本 profile 的 expires_at 推进\"全文件候选\"，\n  // 最后可能取到**另一个 profile** 的到期时间 —— 界面上显示的日期就是错的。\n  // 现在的规则：只有缩进回到同级或更外层才算块结束。\n  if (typeof wanted === 'string' && wanted !== '') {\n    let base\n    for (const line of lines) {\n      const header = sectionOf(line)\n      if (header !== null) {\n        if (base === undefined) {\n          if (header[2].trim() === wanted) base = header[1].length\n          continue\n        }\n        if (header[1].length <= base) break\n        continue\n      }\n      if (base === undefined) continue\n      const expiry = expiryOf(line)\n      if (expiry === null) continue\n      const ms = expiryToMs(Number(expiry[1]))\n      if (ms !== undefined) return ms\n    }\n  }\n\n  // 兜底：全文件里最早的那个（最早到期的最该被提醒）。\n  const found = []\n  for (const line of lines) {\n    const expiry = expiryOf(line)\n    if (expiry === null) continue\n    const ms = expiryToMs(Number(expiry[1]))\n    if (ms !== undefined) found.push(ms)\n  }\n  return found.length === 0 ? undefined : Math.min(...found)\n}\n\n/**\n * 在 PATH 里找一个可执行文件。\n *\n * 这里用 `existsSync` 逐个拼路径检查（而不是 spawn 一次 `--version`）：\n * 它不产生额外进程、不依赖超时，结果也确定；Windows 上额外试 `.cmd/.exe/.bat`。\n * 注意只检查\"存在\"，不检查可执行位 —— 真正执行时若不可执行，spawn 会给出明确错误。\n *\n * @param name - 可执行文件名，如 `arkcli`。\n * @param pathValue - PATH 值，默认取父进程的 PATH。\n * @param exists - 存在性判断，便于测试注入。\n */\nexport function findExecutableOnPath(name, pathValue = process.env.PATH, exists = existsSync) {\n  if (typeof pathValue !== 'string' || pathValue === '') return undefined\n  const suffixes = process.platform === 'win32' ? ['', '.cmd', '.exe', '.bat'] : ['']\n  for (const dir of pathValue.split(delimiter)) {\n    if (dir === '') continue\n    for (const suffix of suffixes) {\n      const candidate = join(dir, `${name}${suffix}`)\n      if (exists(candidate)) return candidate\n    }\n  }\n  return undefined\n}\n\n// ---------------------------------------------------------------------------\n// 输出解析\n// ---------------------------------------------------------------------------\n\n/** 把任意抛出物转成一句可读文本。 */\nfunction messageOf(error) {\n  return error instanceof Error ? error.message : String(error)\n}\n\n/** 最后一行非空文本（arkcli 的人类可读报错经常只在最后一行）。 */\nfunction lastMeaningfulLine(text) {\n  if (typeof text !== 'string') return undefined\n  const lines = text.split('\\n').map((line) => line.trim()).filter((line) => line !== '')\n  return lines.length === 0 ? undefined : lines[lines.length - 1]\n}\n\n/**\n * 解析 arkcli 的 `--format json` 输出。\n *\n * arkcli 成功时把 JSON 打在 stdout；失败时把 `{\"ok\":false,\"error\":{...}}` 也打在\n * **stdout**（不是 stderr）并且退出码非零。另外 stdout 里可能先有一行警告，\n * 所以从第一个 JSON 起始符开始截取。\n *\n * 起点同时考虑 `{` 与 `[`：`models search` 的顶层应答既可能是对象、也可能是数组，\n * 只认 `{` 会把数组截坏（取数组内第一个花括号当起点）。先试最靠前的起始符，\n * 失败再试下一个。\n *\n * @param text - 子进程的 stdout。\n * @returns 成功 `{ok:true, value}`；失败 `{ok:false, error}`（error 一定是可读字符串）。\n */\nexport function parseArkcliJson(text) {\n  if (typeof text !== 'string') return { ok: false, error: '没有可解析的输出' }\n  const trimmed = text.trim()\n  if (trimmed === '') return { ok: false, error: '输出为空' }\n  const starts = [trimmed.indexOf('{'), trimmed.indexOf('[')].filter((index) => index >= 0).sort((left, right) => left - right)\n  const candidates = starts.length === 0 ? [0] : starts\n  let value\n  let failure\n  for (const start of candidates) {\n    try {\n      value = JSON.parse(trimmed.slice(start))\n      failure = undefined\n      break\n    } catch (error) {\n      failure = error\n    }\n  }\n  if (failure !== undefined) return { ok: false, error: `不是合法 JSON：${messageOf(failure)}` }\n  if (value !== null && typeof value === 'object' && value.ok === false) {\n    const raw = value.error\n    const message = raw !== null && typeof raw === 'object' && typeof raw.message === 'string'\n      ? raw.message\n      : typeof raw === 'string' && raw !== '' ? raw : 'arkcli 报错（没有 message）'\n    return { ok: false, error: message }\n  }\n  return { ok: true, value }\n}\n\n/**\n * 该 stdout 是否\"看起来像 JSON 报错\"（决定非零退出时优先用哪条错误文本）。\n *\n * 判据是\"**trim 之后以 `{` 或 `[` 开头**\"，而不是\"包含 `{` 或 `[`\"：Go 的 panic 回溯\n * 形如 `panic: ...\\n\\ngoroutine 1 [running]:\\n...`，里面就有 `[running]` 的 `[`，\n * 旧判据会把整段回溯当成 JSON 去解析，于是用户看到的是\n * `不是合法 JSON：Unexpected token 'r', \"[running]:\" is not valid JSON` ——\n * 真正的原因（panic 的第一行）反而被丢掉。\n */\nfunction looksLikeJsonReport(stdout) {\n  if (typeof stdout !== 'string') return false\n  const trimmed = stdout.trim()\n  return trimmed.startsWith('{') || trimmed.startsWith('[')\n}\n\n// ---------------------------------------------------------------------------\n// 子进程环境\n// ---------------------------------------------------------------------------\n\n/**\n * 构造 arkcli 子进程用的最小环境。\n *\n * 白名单重建，**绝不继承** `ARK_API_KEY` / `ARK_PROFILE` / `ARK_BASE_URL` / `VOLC_*`\n * / `ARKCLI_ALLOW_HEADLESS_*`：这些一旦被继承，arkcli 就会把宿主自己的凭据与上下文\n * 当成\"当前账号\"，多账号隔离当场失效（而且宿主的 key 会被写进别的账号目录）。\n *\n * `HOME` 是必填的：arkcli 的状态目录是 `$HOME/.arkcli` 且无法用环境变量覆盖，\n * 少传 HOME 就等于在宿主的家目录里乱写。\n *\n * @param home - 该账号的 HOME（绝对路径）。\n * @param extra - 追加/覆盖的键，值为 undefined 的键会被跳过。\n * @throws 当 home 缺失或为空。\n */\nexport function buildChildEnv(home, extra) {\n  if (typeof home !== 'string' || home === '') {\n    throw new Error('必须显式给定 HOME：arkcli 把状态放在 $HOME/.arkcli 且没有环境变量可以覆盖，多账号隔离完全依赖它。')\n  }\n  const put = (target, key, value) => {\n    if (value !== undefined) target[key] = value\n  }\n  const env = {}\n  put(env, 'PATH', process.env.PATH)\n  env.HOME = home\n  env.LANG = process.env.LANG ?? 'C.UTF-8'\n  env.LC_ALL = process.env.LC_ALL ?? 'C.UTF-8'\n  put(env, 'TMPDIR', process.env.TMPDIR ?? tmpdir())\n  env.NO_COLOR = '1'\n  env.ARKCLI_NO_UPDATE_NOTIFIER = '1'\n  env.ARKCLI_CALLER_TYPE = 'ai_agent'\n  env.ARKCLI_CALLER_NAME = 'dsh-ark-coding-provider'\n  for (const [key, value] of Object.entries(extra ?? {})) put(env, key, value)\n  return env\n}\n\n// ---------------------------------------------------------------------------\n// 归一化\n// ---------------------------------------------------------------------------\n\n/** 有限数字，否则 undefined。 */\nfunction finiteNumber(value) {\n  return typeof value === 'number' && Number.isFinite(value) ? value : undefined\n}\n\n/** 有限正数，否则 undefined（`context_window: null` 之类一律视为\"未知\"）。 */\nfunction positiveNumber(value) {\n  const number = finiteNumber(value)\n  return number !== undefined && number > 0 ? number : undefined\n}\n\n/** 非空字符串，否则 undefined。 */\nfunction stringOrUndefined(value) {\n  return typeof value === 'string' && value !== '' ? value : undefined\n}\n\n/** 只保留字符串元素的数组。 */\nfunction stringArray(value) {\n  return Array.isArray(value) ? value.filter((item) => typeof item === 'string') : []\n}\n\n/** 百分比：clamp 到 0..100，最多两位小数；非数字则 undefined。 */\nexport function normalizePercent(value) {\n  const number = finiteNumber(value)\n  if (number === undefined) return undefined\n  const clamped = Math.max(0, Math.min(100, number))\n  return Math.round(clamped * 100) / 100\n}\n\n/**\n * `reset_at` → epoch 毫秒。\n *\n * 上游给 RFC3339（带 +08:00 偏移）字符串；如果哪天它改成数字，秒与毫秒都认\n * （> 1e11 视为毫秒）。解析不出来就 undefined —— **绝不返回 NaN**，否则\n * `new Date(NaN)` 会一路把界面显示成 Invalid Date。\n */\nexport function parseResetAt(value) {\n  if (typeof value === 'number' && Number.isFinite(value)) {\n    return usableDateMs(value > 1e11 ? value : value * 1000)\n  }\n  if (typeof value !== 'string' || value.trim() === '') return undefined\n  return usableDateMs(Date.parse(value))\n}\n\n/**\n * 时间戳是否落在一个能正常显示的范围里。\n *\n * `new Date(-1000).toLocaleString()` 渲染出 1970-01-01，`new Date(1e300)` 渲染出\n * \"Invalid Date\" —— 用户看到的是**假日期**，比什么都不显示更糟。而 `formatClock`\n * 里的 try/catch 拦不住这两种（它们根本不抛）。所以范围校验必须在这里做。\n */\nfunction usableDateMs(value) {\n  if (typeof value !== 'number' || !Number.isFinite(value)) return undefined\n  if (value <= 0 || value > 8.64e15) return undefined\n  return value\n}\n\n/** 上游 `expires_at` 是秒；> 1e11 说明已经是毫秒了，别乘两次。 */\nfunction expiryToMs(raw) {\n  if (!Number.isFinite(raw) || raw <= 0) return undefined\n  return usableDateMs(raw > 1e11 ? raw : raw * 1000)\n}\n\n/** 时间戳 → epoch 毫秒（数字直用，字符串走 Date.parse）。 */\nfunction epochMs(value) {\n  const number = finiteNumber(value)\n  if (number !== undefined) return number\n  if (typeof value === 'string' && value.trim() !== '') {\n    const parsed = Date.parse(value)\n    return Number.isNaN(parsed) ? undefined : parsed\n  }\n  return undefined\n}\n\n/** 上游 label → 稳定窗口键。 */\nexport function periodKeyOf(label) {\n  const key = typeof label === 'string' ? label.trim().toLowerCase() : ''\n  if (key === 'session' || key === '5h') return 'session'\n  if (key === 'weekly' || key === 'week') return 'weekly'\n  if (key === 'monthly' || key === 'month') return 'monthly'\n  return key\n}\n\n/** 窗口的规范顺序：5 小时 → 每周 → 每月 → 其它（保持上游相对顺序）。 */\nconst PERIOD_ORDER = { session: 0, weekly: 1, monthly: 2 }\n\n/** 归一化一个额度窗口。 */\nexport function normalizePeriod(row) {\n  if (row === null || typeof row !== 'object') return undefined\n  const label = stringOrUndefined(row.label) ?? ''\n  const used = finiteNumber(row.used)\n  const total = finiteNumber(row.total)\n  return {\n    label,\n    key: periodKeyOf(label),\n    used,\n    total,\n    percent: normalizePercent(row.percent),\n    resetAt: parseResetAt(row.reset_at ?? row.resetAt),\n    // CodingPlan 只给 percent（used/total 被 omitempty 掉了），AgentPlan 才给绝对值。\n    hasTotals: used !== undefined && total !== undefined,\n  }\n}\n\n/** 归一化 `usage plan` 的一个套餐条目。 */\nexport function normalizeUsageItem(row) {\n  const source = row !== null && typeof row === 'object' ? row : {}\n  const periods = (Array.isArray(source.periods) ? source.periods : [])\n    .map(normalizePeriod)\n    .filter((period) => period !== undefined)\n  // Array.prototype.sort 在 V8 上是稳定的，因此同序的\"其它\"窗口保持上游顺序。\n  periods.sort((left, right) => (PERIOD_ORDER[left.key] ?? 99) - (PERIOD_ORDER[right.key] ?? 99))\n  return {\n    product: stringOrUndefined(source.product),\n    edition: stringOrUndefined(source.edition),\n    tier: stringOrUndefined(source.tier),\n    seatId: stringOrUndefined(source.seat_id ?? source.seatId),\n    subscribed: source.subscribed === true,\n    periods,\n    updatedAt: epochMs(source.updated_at ?? source.updatedAt),\n    // 单个套餐出错时其它套餐仍然返回，所以错误挂在条目上而不是整个应答上。\n    error: stringOrUndefined(source.error),\n  }\n}\n\n/** 归一化一个模型条目。 */\nexport function normalizeModel(row) {\n  const source = row !== null && typeof row === 'object' ? row : {}\n  const id = stringOrUndefined(source.name)\n  const displayName = stringOrUndefined(source.display_name)\n  return {\n    id,\n    name: displayName ?? id,\n    displayName,\n    version: stringOrUndefined(source.primary_version),\n    contextWindow: positiveNumber(source.context_window),\n    maxInputTokens: positiveNumber(source.max_input_tokens),\n    maxOutputTokens: positiveNumber(source.max_completion_tokens),\n    inputModalities: stringArray(source.input_modalities),\n    outputModalities: stringArray(source.output_modalities),\n    capabilities: source.capabilities !== null && typeof source.capabilities === 'object' ? source.capabilities : {},\n    cacheTypes: stringArray(source.cache_types),\n    lifecycleStatus: stringOrUndefined(source.lifecycle_status),\n    updateTime: stringOrUndefined(source.update_time),\n  }\n}\n\n/** `models search` 的应答外壳有三种：裸数组、`{items}`、`{data:{items}}`。 */\nexport function modelsItemsOf(value) {\n  if (Array.isArray(value)) return value\n  if (value !== null && typeof value === 'object') {\n    if (Array.isArray(value.items)) return value.items\n    if (value.data !== null && typeof value.data === 'object' && Array.isArray(value.data.items)) return value.data.items\n  }\n  return []\n}\n\n/**\n * 从 `profile apikey get` 的输出里抠出 API key。\n *\n * 这个子命令的确切输出形状没有实测（文档只说它\"机器可读\"），所以三种都认：\n * 裸字符串、JSON 对象（`api_key`/`apiKey`/`default_api_key`/`key`，含 `data` 包一层）、\n * 以及 JSON 字符串。裸文本则在每一行里找\"像 key 的单行 token\"。\n */\nexport function extractApiKey(text) {\n  if (typeof text !== 'string') return undefined\n  const trimmed = text.trim()\n  if (trimmed === '') return undefined\n  // 可能前面还有一行日志，所以从第一个 `{` / `\"` 开始试；失败再退回按行找 token。\n  const brace = trimmed.indexOf('{')\n  const quote = trimmed.indexOf('\"')\n  const start = brace >= 0 && (quote === -1 || brace < quote) ? brace : quote\n  if (start >= 0) {\n    try {\n      const parsed = JSON.parse(trimmed.slice(start))\n      if (typeof parsed === 'string') {\n        if (parsed.trim() !== '') return parsed.trim()\n      } else {\n        const found = apiKeyOf(parsed)\n        if (found !== undefined) return found\n      }\n    } catch { /* 不是 JSON，按裸文本继续找 */ }\n  }\n  for (const line of trimmed.split('\\n')) {\n    const candidate = line.trim()\n    if (/^[A-Za-z0-9._-]{8,}$/.test(candidate)) return candidate\n  }\n  return undefined\n}\n\n/** 在对象里按候选键名找字符串 key。 */\nfunction apiKeyOf(value) {\n  if (value === null || typeof value !== 'object') return undefined\n  for (const key of ['api_key', 'apiKey', 'default_api_key', 'key']) {\n    const candidate = value[key]\n    if (typeof candidate === 'string' && candidate.trim() !== '') return candidate.trim()\n  }\n  if (value.data !== null && typeof value.data === 'object') return apiKeyOf(value.data)\n  return undefined\n}\n\n// ---------------------------------------------------------------------------\n// ArkCli\n// ---------------------------------------------------------------------------\n\n/**\n * arkcli 进程封装。\n *\n * 所有外部依赖都可注入（spawn / fetch / now / exists），测试里给假实现即可完全离线。\n */\nexport class ArkCli {\n  /**\n   * @param options - 依赖与配置。\n   * @param options.dshHome - DSH 数据目录；托管安装与账号 HOME 都在它下面。\n   * @param options.binPath - 配置里的 arkcli 可执行文件路径（优先级最高）。\n   * @param options.logger - 可选日志对象（用 debug 通道）。\n   * @param options.spawn - 子进程工厂，默认 `node:child_process.spawn`。\n   * @param options.fetchImpl - fetch，默认全局 fetch。\n   * @param options.now - 时钟，默认 `Date.now`。\n   * @param options.packageVersion - 安装时固定的版本；缺省 latest。\n   * @param options.pathEnv - 用于查找 PATH 上的 arkcli，默认父进程 PATH。\n   * @param options.exists - 存在性判断，默认 `fs.existsSync`。\n   * @param options.mkdir - 建目录，默认 `fs.mkdirSync`。\n   */\n  constructor(options = {}) {\n    const {\n      dshHome,\n      binPath,\n      logger,\n      spawn = nodeSpawn,\n      fetchImpl = globalThis.fetch,\n      now = Date.now,\n      packageVersion,\n      pathEnv = process.env.PATH,\n      exists = existsSync,\n      mkdir = mkdirSync,\n    } = options\n    this.dshHome = dshHome\n    this.binPath = typeof binPath === 'string' && binPath !== '' ? binPath : undefined\n    this.logger = logger\n    this.spawn = spawn\n    this.fetchImpl = fetchImpl\n    this.now = now\n    this.packageVersion = typeof packageVersion === 'string' && packageVersion !== '' ? packageVersion : undefined\n    this.pathEnv = pathEnv\n    this.exists = exists\n    this.mkdir = mkdir\n  }\n\n  /**\n   * 解析到底用哪个 arkcli。\n   *\n   * 顺序：配置里的 binPath（用户明确指定，最可信）→ 本插件托管安装的 bin →\n   * PATH 上的 arkcli。第三个是真实查找（`findExecutableOnPath`），不是\"试着跑一下\"。\n   *\n   * @returns `{path, source}`；都没有时 `path` 为 undefined。\n   */\n  async resolveBin() {\n    if (this.binPath !== undefined && this.exists(this.binPath)) return { path: this.binPath, source: 'config' }\n    if (typeof this.dshHome === 'string' && this.dshHome !== '') {\n      const managed = managedBinPath(this.dshHome)\n      if (this.exists(managed)) return { path: managed, source: 'managed' }\n    }\n    const onPath = findExecutableOnPath('arkcli', this.pathEnv, this.exists)\n    if (onPath !== undefined) return { path: onPath, source: 'path' }\n    return { path: undefined, source: undefined }\n  }\n\n  /** 无状态命令用的 HOME；不主动创建目录（`--version` 不会去写状态）。 */\n  #neutralHome(home) {\n    if (typeof home === 'string' && home !== '') return home\n    const base = typeof this.dshHome === 'string' && this.dshHome !== ''\n      ? this.dshHome\n      : (process.env.DSH_HOME ?? join(process.env.HOME ?? '.', '.dsh'))\n    return neutralHomeDir(base)\n  }\n\n  /**\n   * 起一个子进程并把输出收全。\n   *\n   * 超时会 `SIGKILL` 并返回 error='超时'。返回值里的 `failure` 字段只在本模块内部\n   * 用来区分\"超时 / 起不来 / 正常退出非零\"，不进 `run()` 的对外结果。\n   */\n  async #spawnCollect(bin, args, options) {\n    const { env, timeoutMs } = options\n    return await new Promise((resolve) => {\n      let child\n      try {\n        // `detached: true`：起独立进程组，这样超时能整组带走（见 #killTree）。\n        child = this.spawn(bin, args, { stdio: ['ignore', 'pipe', 'pipe'], env, detached: true })\n      } catch (error) {\n        resolve({ ok: false, code: null, stdout: '', stderr: '', error: `无法启动 ${bin}：${messageOf(error)}`, failure: 'spawn' })\n        return\n      }\n      let stdout = ''\n      let stderr = ''\n      let settled = false\n      let timer\n      const done = (result) => {\n        if (settled) return\n        settled = true\n        if (timer !== undefined) clearTimeout(timer)\n        resolve(result)\n      }\n      child.stdout?.on?.('data', (chunk) => {\n        if (stdout.length < MAX_CHILD_OUTPUT_CHARS) stdout += String(chunk)\n      })\n      child.stderr?.on?.('data', (chunk) => {\n        if (stderr.length < MAX_CHILD_OUTPUT_CHARS) stderr += String(chunk)\n      })\n      child.on?.('error', (error) => {\n        done({ ok: false, code: null, stdout, stderr, error: `执行 ${bin} 失败：${messageOf(error)}`, failure: 'spawn' })\n      })\n      child.on?.('close', (code, signal) => {\n        done({\n          ok: code === 0,\n          code,\n          stdout,\n          stderr,\n          error: code === 0 ? undefined : `退出码 ${code ?? signal}`,\n          failure: code === 0 ? undefined : 'exit',\n        })\n      })\n      if (typeof timeoutMs === 'number' && timeoutMs > 0) {\n        timer = setTimeout(() => {\n          this.#killTree(child)\n          done({ ok: false, code: null, stdout, stderr, error: '超时', failure: 'timeout' })\n        }, timeoutMs)\n      }\n    })\n  }\n\n  /**\n   * 杀一个子进程**及其后代**。\n   *\n   * `node_modules/.bin/arkcli` 是个 node 包装脚本，它用 `execFileSync` 阻塞地去跑真正的\n   * Go 二进制。**杀掉包装进程不会杀掉那个 Go 孙子进程**：实测 SIGKILL 掉包装之后，\n   * Go 二进制被 init 收养继续活着（PPID=1），还占着回环端口和 `<HOME>/.arkcli` 下的\n   * 锁文件 —— 也就是说\"超时\"并没有真的停下工作，反复超时还会累积 root 进程。\n   *\n   * 所以子进程一律以 `detached: true` 起独立进程组，这里按**进程组**杀（负 pid）。\n   * 登录会话一直是这么做的（见 `#kill`），`run()` 与安装用的 npm 当时漏了这一半。\n   */\n  #killTree(child) {\n    const pid = child?.pid\n    if (typeof pid === 'number' && pid > 0) {\n      try {\n        process.kill(-pid, 'SIGKILL')\n        return\n      } catch { /* 进程组可能已经没了，退回杀单个进程 */ }\n    }\n    try { child?.kill?.('SIGKILL') } catch { /* 已经退出就无所谓 */ }\n  }\n\n  /**\n   * 跑一次 arkcli。\n   *\n   * @param args - 参数数组（不含可执行文件名）。\n   * @param options - `home`（必填，作为子进程 HOME）、超时、额外环境变量。\n   * @returns `{ok, code, stdout, stderr, json, error}`；`json` 是解析成功后的值。\n   * @throws 当 `home` 缺失（多账号隔离依赖它，不允许\"随手用父进程 HOME\"）。\n   */\n  async run(args, options = {}) {\n    const { home, timeoutMs = DEFAULT_RUN_TIMEOUT_MS, env } = options\n    const childEnv = buildChildEnv(home, env)\n    const resolved = await this.resolveBin()\n    if (resolved.path === undefined) {\n      return { ok: false, code: null, stdout: '', stderr: '', json: undefined, error: '找不到 arkcli：请先安装，或在设置里指定可执行文件路径。' }\n    }\n    const collected = await this.#spawnCollect(resolved.path, args, { env: childEnv, timeoutMs })\n    const parsed = parseArkcliJson(collected.stdout)\n    const json = parsed.ok ? parsed.value : undefined\n\n    if (collected.ok) return { ok: true, code: collected.code, stdout: collected.stdout, stderr: collected.stderr, json, error: undefined }\n\n    // 非零退出：优先用 arkcli 自己给的 JSON message，其次 stderr 最后一行，最后才是退出码。\n    //\n    // 注意两个流都要看：arkcli 的约定是「stdout 只放结构化结果，错误与解释走 stderr」，\n    // 实测未登录时整个 {\"ok\":false,\"error\":{...}} 信封是打在 **stderr** 上的。只看 stdout\n    // 的话，这里会退化成 stderr 的最后一行 —— 也就是一个孤零零的 `}`，界面里毫无意义。\n    const errorFrom = (text) => {\n      if (!looksLikeJsonReport(text)) return undefined\n      const candidate = parseArkcliJson(text)\n      return candidate.ok === false ? candidate.error : undefined\n    }\n    let error\n    if (collected.failure === 'timeout') error = '超时'\n    else if (collected.failure === 'spawn') error = collected.error\n    else {\n      error = errorFrom(collected.stderr)\n        ?? errorFrom(collected.stdout)\n        ?? lastMeaningfulLine(collected.stderr)\n        ?? collected.error\n    }\n    return { ok: false, code: collected.code, stdout: collected.stdout, stderr: collected.stderr, json, error }\n  }\n\n  /**\n   * 当前 arkcli 是否可用。\n   *\n   * @returns `{installed, path, version, source, error?}`。\n   */\n  async status(options = {}) {\n    const resolved = await this.resolveBin()\n    if (resolved.path === undefined) {\n      return {\n        installed: false,\n        path: undefined,\n        version: undefined,\n        source: undefined,\n        error: '未安装 arkcli：可以在这里一键安装，或把 arkcli 放到 PATH 上。',\n      }\n    }\n    const result = await this.run(['--version'], { home: this.#neutralHome(options.home), timeoutMs: 30_000 })\n    const text = `${result.stdout}\\n${result.stderr}`\n    const match = /(\\d+\\.\\d+\\.\\d+(?:[-+][0-9A-Za-z.-]+)?)/.exec(text)\n    return {\n      installed: result.ok,\n      path: resolved.path,\n      version: match?.[1],\n      source: resolved.source,\n      error: result.ok ? undefined : result.error,\n    }\n  }\n\n  /**\n   * 把 CLI 装到本插件的托管目录下。\n   *\n   * 走 `npm install --prefix <dir> <pkg>@<version>`，postinstall 会自己下载对应平台的\n   * Go 二进制（实测约 12 秒）。装完重新解析 bin 并跑一次 status 确认真的能用。\n   *\n   * @param options.version - 指定版本；缺省 latest（或构造时的 packageVersion）。\n   * @returns `{ok, path, version, error}`。\n   */\n  async install(options = {}) {\n    const { version, timeoutMs = INSTALL_TIMEOUT_MS } = options\n    if (typeof this.dshHome !== 'string' || this.dshHome === '') {\n      return { ok: false, path: undefined, version: undefined, error: '没有 DSH_HOME，无法确定安装目录。' }\n    }\n    const dir = managedInstallDir(this.dshHome)\n    try {\n      this.mkdir(dir, { recursive: true })\n    } catch (error) {\n      return { ok: false, path: undefined, version: undefined, error: `无法创建安装目录 ${dir}：${messageOf(error)}` }\n    }\n    const wanted = version ?? this.packageVersion ?? DEFAULT_INSTALL_VERSION\n    const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm'\n    const args = ['install', '--prefix', dir, `${ARKCLI_PACKAGE}@${wanted}`, ...NPM_INSTALL_FLAGS]\n    // npm 也用最小环境：否则 npm 会把宿主 HOME 下的 .npm 缓存/配置带进这次安装。\n    // 中性 HOME 建不出来也无所谓（npm 自己会建缓存目录），但环境绝不能退回\"继承父进程\"。\n    const npmHome = this.#neutralHome()\n    try { this.mkdir(npmHome, { recursive: true }) } catch { /* 让 npm 自己决定 */ }\n    const env = buildChildEnv(npmHome)\n    const collected = await this.#spawnCollect(npm, args, { env, timeoutMs })\n    if (!collected.ok) {\n      const tail = collected.stderr.trim().slice(-400) || collected.stdout.trim().slice(-400) || collected.error\n      return { ok: false, path: undefined, version: undefined, error: `安装 ${ARKCLI_PACKAGE}@${wanted} 失败：${tail}` }\n    }\n    const resolved = await this.resolveBin()\n    if (resolved.path === undefined) {\n      return { ok: false, path: undefined, version: undefined, error: `npm 退出码为 0，但 ${managedBinPath(this.dshHome)} 不存在。` }\n    }\n    const status = await this.status({ home: this.#neutralHome() })\n    if (!status.installed) {\n      return { ok: false, path: resolved.path, version: status.version, error: status.error ?? '安装后 arkcli 无法执行。' }\n    }\n    this.logger?.debug?.(`[arkcli] 已安装 ${ARKCLI_PACKAGE}@${wanted} → ${resolved.path}`)\n    return { ok: true, path: resolved.path, version: status.version ?? wanted, error: undefined }\n  }\n\n  /**\n   * 查套餐额度（控制面，需要 SSO）。\n   *\n   * CodingPlan 的窗口只有 percent；AgentPlan 有 used/total。某个套餐出错时\n   * 错误挂在 `items[].error` 上，其余套餐照常返回 —— 这里原样保留这种隔离。\n   *\n   * @returns `{ok, viewer, items, error}`。\n   */\n  async usagePlan(options = {}) {\n    const { home, timeoutMs = DEFAULT_CONTROL_PLANE_TIMEOUT_MS } = options\n    const result = await this.run(['usage', 'plan', '--format', 'json'], { home, timeoutMs })\n    if (!result.ok) return { ok: false, viewer: undefined, items: [], error: result.error }\n    const value = result.json\n    if (value === null || typeof value !== 'object') {\n      return { ok: false, viewer: undefined, items: [], error: 'usage plan 没有返回 JSON 对象。' }\n    }\n    const items = (Array.isArray(value.items) ? value.items : []).map(normalizeUsageItem)\n    const viewer = value.viewer !== null && typeof value.viewer === 'object' ? value.viewer : undefined\n    return { ok: true, viewer, items, error: undefined }\n  }\n\n  /**\n   * 搜模型（控制面）。\n   *\n   * `keyword` 会作为 `--keyword` 传给 CLI；该参数名来自控制面搜索的通用约定，\n   * 未逐一实测（`--format json --size 0` 是实测过的）。\n   *\n   * @returns `{ok, items, updatedAt, error}`。\n   */\n  async modelsSearch(options = {}) {\n    const { home, keyword, size = 0, timeoutMs = DEFAULT_CONTROL_PLANE_TIMEOUT_MS } = options\n    const args = ['models', 'search', '--format', 'json', '--size', String(size)]\n    if (typeof keyword === 'string' && keyword.trim() !== '') args.push('--keyword', keyword.trim())\n    const result = await this.run(args, { home, timeoutMs })\n    if (!result.ok) return { ok: false, items: [], updatedAt: undefined, error: result.error }\n    const value = result.json\n    if (value === undefined) return { ok: false, items: [], updatedAt: undefined, error: 'models search 没有返回 JSON。' }\n    const items = modelsItemsOf(value).filter((row) => row !== null && typeof row === 'object').map(normalizeModel)\n    const envelope = Array.isArray(value) ? undefined : value\n    const updatedAt = epochMs(envelope?.updated_at ?? envelope?.updatedAt)\n    return { ok: true, items, updatedAt, error: undefined }\n  }\n\n  /**\n   * 当前登录身份。\n   *\n   * 字段名以文档/binary 里的观察为准，多余或缺失都当正常。\n   *\n   * @returns `{ok, userId, userName, accountId, isRoot, authMethod, loggedIn, raw, error}`。\n   */\n  async whoami(options = {}) {\n    const { home, timeoutMs = DEFAULT_RUN_TIMEOUT_MS } = options\n    const result = await this.run(['auth', 'whoami', '--format', 'json'], { home, timeoutMs })\n    const value = result.json !== null && typeof result.json === 'object' ? result.json : {}\n    return {\n      ok: result.ok,\n      userId: stringOrUndefined(value.user_id),\n      userName: stringOrUndefined(value.user_name),\n      accountId: stringOrUndefined(value.account_id),\n      isRoot: typeof value.is_root === 'boolean' ? value.is_root : undefined,\n      authMethod: stringOrUndefined(value.auth_method),\n      loggedIn: value.logged_in === true,\n      raw: value,\n      error: result.error,\n    }\n  }\n\n  /**\n   * 登录状态。\n   *\n   * @returns `{ok, loggedIn, authMethod, raw, error}`。\n   */\n  async authStatus(options = {}) {\n    const { home, timeoutMs = DEFAULT_RUN_TIMEOUT_MS } = options\n    const result = await this.run(['auth', 'status', '--format', 'json'], { home, timeoutMs })\n    const value = result.json !== null && typeof result.json === 'object' ? result.json : {}\n    return {\n      ok: result.ok,\n      loggedIn: value.logged_in === true,\n      authMethod: stringOrUndefined(value.auth_method),\n      raw: value,\n      error: result.error,\n    }\n  }\n\n  /**\n   * 取当前 profile 的默认 API key（明文）。\n   *\n   * 不加 `--format json`：这个子命令本身就标称\"机器可读\"，加参数反而可能改变输出。\n   * 形状未实测，所以解析按多种可能来（见 `extractApiKey`）。\n   *\n   * @returns `{ok, apiKey, error}`。\n   */\n  async profileApiKey(options = {}) {\n    const { home, timeoutMs = DEFAULT_RUN_TIMEOUT_MS } = options\n    const result = await this.run(['profile', 'apikey', 'get'], { home, timeoutMs })\n    if (!result.ok) return { ok: false, apiKey: undefined, error: result.error }\n    const apiKey = extractApiKey(result.stdout)\n    if (apiKey === undefined) return { ok: false, apiKey: undefined, error: '没有从 profile apikey get 的输出里解析出 API key。' }\n    return { ok: true, apiKey, error: undefined }\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 登录会话（GUI 回调转发）\n// ---------------------------------------------------------------------------\n\n/**\n * 造一个 fetch 形状的请求函数，底层走 `node:http`。\n *\n * **为什么不用全局 fetch**：Fetch 规范把 `Host` 列为 forbidden header name，Node 24 的\n * undici 会**静默丢掉**我们设的 `host`（2026-10-16 实测：服务端收到的是自己算出来的\n * `127.0.0.1:<port>`，我们想送的 `localhost:<port>` 根本没出去）。而 arkcli 的回环\n * 监听会校验 Host，头被改掉就可能被判 `invalid host`、登录永远完不成。`node:http`\n * 不做这层过滤，实测能把我们指定的 Host 原样送出去。\n *\n * 只服务于回环 http 回调：不做 TLS、不跟重定向，返回值只要求 fetch 的\n * `{ok, status, text()}` 子集。\n *\n * @param requestImpl - `node:http.request`，可注入以便离线测试。\n */\nexport function createHttpFetch(requestImpl = httpRequest) {\n  return async function httpFetch(url, init = {}) {\n    const target = new URL(url)\n    return await new Promise((resolve, reject) => {\n      const request = requestImpl({\n        protocol: target.protocol,\n        hostname: target.hostname,\n        port: target.port === '' ? undefined : target.port,\n        path: `${target.pathname}${target.search}`,\n        method: init.method ?? 'GET',\n        headers: init.headers ?? {},\n      }, (response) => {\n        const chunks = []\n        response.on('data', (chunk) => { chunks.push(String(chunk)) })\n        response.on('end', () => {\n          const status = response.statusCode ?? 0\n          resolve({\n            ok: status >= 200 && status < 300,\n            status,\n            headers: response.headers ?? {},\n            text: async () => chunks.join(''),\n          })\n        })\n      })\n      request.on('error', reject)\n      request.end()\n    })\n  }\n}\n\n/**\n * SSO 登录会话管理器。\n *\n * 一次登录 = 一个常驻子进程 + 一个回环监听。`start()` 把授权 URL 交出去，\n * 用户在浏览器里完成 SSO（跳转会失败，但地址栏留下回调 URL），`submit()` 把那条\n * URL 转发到本机监听上完成登录。详见文件头。\n */\nexport class ArkCliLogin {\n  /**\n   * @param options - 与 `ArkCli` 相同的依赖；会用它建一个内部的 `ArkCli` 来解析 bin。\n   * @param options.fetchImpl - 自定义的请求实现；缺省用 `createHttpFetch()`（见其说明：\n   *   全局 fetch 无法把 Host 头送出去，而回环监听会校验 Host）。\n   * @param options.requestImpl - 透传给 `createHttpFetch` 的 `node:http.request`。\n   * @param options.refFactory - 生成会话 ref，缺省随机 hex。\n   */\n  constructor(options = {}) {\n    this.cli = new ArkCli(options)\n    this.spawn = options.spawn ?? nodeSpawn\n    this.fetchImpl = options.fetchImpl ?? createHttpFetch(options.requestImpl)\n    this.now = options.now ?? Date.now\n    this.logger = options.logger\n    this.refFactory = typeof options.refFactory === 'function' ? options.refFactory : () => randomBytes(6).toString('hex')\n    /** @type {Map<string, object>} */\n    this.sessions = new Map()\n  }\n\n  /** 当前活着的会话数（含已经 done/expired 但还没被回收的）。 */\n  size() {\n    return this.sessions.size\n  }\n\n  /** 杀子进程（含它执行出来的孙子进程；已退出的忽略）。 */\n  #kill(session) {\n    if (session.exited) return\n    const pid = session.child.pid\n    // 关键：`node_modules/.bin/arkcli` 是个 node 包装脚本，它用 `execFileSync` 阻塞地\n    // 去跑真正的 Go 二进制。**杀包装进程不会杀掉 Go 孙子进程** —— 实测 SIGKILL 掉包装之后，\n    // Go 二进制被 init 收养、回环端口继续 LISTEN，用户以为取消了其实没有（端口还占着，\n    // 下一次登录又会起一个新的）。所以登录会话一律以 `detached: true` 起独立进程组，\n    // 这里按**进程组**杀（负 pid），把包装和它 exec 出来的二进制一起带走。\n    try {\n      if (typeof pid === 'number' && pid > 0) process.kill(-pid, 'SIGKILL')\n      else session.child.kill('SIGKILL')\n    } catch {\n      try { session.child.kill('SIGKILL') } catch { /* 已经退出就无所谓 */ }\n    }\n  }\n\n  /** 从表里移除并唤醒所有等待者。 */\n  #drop(session) {\n    this.sessions.delete(session.ref)\n    for (const waiter of session.waiters.splice(0)) waiter()\n  }\n\n  /** 彻底收尾：清定时器 + 杀子进程 + 移出表。 */\n  #dispose(session) {\n    if (session.ttlTimer !== undefined) {\n      clearTimeout(session.ttlTimer)\n      session.ttlTimer = undefined\n    }\n    this.#kill(session)\n    this.#drop(session)\n  }\n\n  /**\n   * 发起登录：起 `auth login --no-browser`，从输出里抠出授权 URL 与回环端口。\n   *\n   * @param options - `home`（必填）、等 URL 的超时、会话 TTL、调用方自定义的 ref。\n   * @returns `{ok, ref, url, port, error}`。\n   */\n  async start(options = {}) {\n    const { home, timeoutMs = LOGIN_START_TIMEOUT_MS, ttlMs = LOGIN_TTL_MS, ref = this.refFactory() } = options\n    const childEnv = buildChildEnv(home)\n    const resolved = await this.cli.resolveBin()\n    if (resolved.path === undefined) {\n      return { ok: false, ref, url: undefined, port: undefined, error: '找不到 arkcli：请先安装，或在设置里指定可执行文件路径。' }\n    }\n    let child\n    try {\n      // `detached: true` 让子进程成为独立进程组组长：这样 `#kill` 能按组把\n      // 包装脚本和它 exec 出来的 Go 二进制一起收掉（原因见 `#kill`）。\n      child = this.spawn(resolved.path, ['auth', 'login', '--no-browser'], { stdio: ['ignore', 'pipe', 'pipe'], env: childEnv, detached: true })\n    } catch (error) {\n      return { ok: false, ref, url: undefined, port: undefined, error: `无法启动 arkcli：${messageOf(error)}` }\n    }\n    // 同一个 ref 再次 start：先把旧会话收掉，避免留下孤儿进程。\n    const previous = this.sessions.get(ref)\n    if (previous !== undefined) this.#dispose(previous)\n    const session = {\n      ref,\n      home,\n      child,\n      url: undefined,\n      port: undefined,\n      state: 'pending',\n      code: undefined,\n      error: undefined,\n      output: '',\n      note: undefined,\n      // 身份由调用方另外用 whoami 解析；这里明确\"还没解析\"。\n      identityUnknown: true,\n      createdAt: this.now(),\n      exited: false,\n      ttlTimer: undefined,\n      waiters: [],\n    }\n    this.sessions.set(ref, session)\n    this.logger?.debug?.(`[arkcli] auth login 已启动 ref=${ref}`)\n\n    return await new Promise((resolve) => {\n      let settled = false\n      let startTimer\n      const settle = (result) => {\n        if (settled) return\n        settled = true\n        clearTimeout(startTimer)\n        resolve(result)\n      }\n      const onChunk = (chunk) => {\n        if (session.output.length < MAX_CHILD_OUTPUT_CHARS) session.output += String(chunk)\n        const urlMatch = /https:\\/\\/\\S+/.exec(session.output)\n        const portMatch = /callbackPort=(\\d+)/.exec(session.output)\n        if (urlMatch === null || portMatch === null) return\n        session.url = urlMatch[0]\n        session.port = Number(portMatch[1])\n        // TTL 只武装一次。以前每个 data 事件都重新武装（等于\"只要有输出就永不过期\"），\n        // 而且成功后**不清掉**：登录成功 10 分钟后再看设置页，会话状态已经被 TTL 回调\n        // 从 done 改写成 expired，界面显示\"登录会话已过期\"，纯属误报。\n        if (session.ttlTimer !== undefined) {\n          settle({ ok: true, ref, url: session.url, port: session.port })\n          return\n        }\n        session.ttlTimer = setTimeout(() => {\n          session.ttlTimer = undefined\n          // 已经有结论（成功/失败）就不要再改写成\"过期\"。\n          if (session.state !== 'pending') return\n          session.state = 'expired'\n          session.error = '登录会话已过期，请重新发起授权。'\n          this.#kill(session)\n          for (const waiter of session.waiters.splice(0)) waiter()\n        }, ttlMs)\n        // 定时器不该单独把进程吊住（子进程句柄本来就会撑着事件循环）。\n        session.ttlTimer.unref?.()\n        settle({ ok: true, ref, url: session.url, port: session.port })\n      }\n      child.stdout?.on?.('data', onChunk)\n      child.stderr?.on?.('data', onChunk)\n      child.on?.('error', (error) => {\n        session.state = 'error'\n        session.error = messageOf(error)\n        this.#dispose(session)\n        settle({ ok: false, ref, url: session.url, port: session.port, error: `arkcli auth login 无法启动：${session.error}` })\n      })\n      child.on?.('close', (code) => {\n        session.exited = true\n        session.code = code\n        if (session.state === 'pending') session.state = code === 0 ? 'done' : 'error'\n        if (code !== 0 && session.error === undefined) {\n          session.error = lastMeaningfulLine(session.output) ?? `arkcli auth login 退出码 ${code}`\n        }\n        // 已经有结论，就别再让 TTL 定时器把它改写成 expired —— 否则一次**成功**的登录\n        // 在 10 分钟后会显示成\"登录会话已过期\"。\n        if (session.ttlTimer !== undefined) {\n          clearTimeout(session.ttlTimer)\n          session.ttlTimer = undefined\n        }\n        // 输出与子进程句柄都可以放掉了：结论已经记在 state/error 上，poll 只需要它。\n        // （下面提前退出分支要用到输出，所以先取好 tail 再清。）\n        const tail = lastMeaningfulLine(session.output)\n        session.output = ''\n        for (const waiter of session.waiters.splice(0)) waiter()\n        if (!settled) {\n          const error = `arkcli auth login 提前退出（退出码 ${code}）：${tail ?? '没有输出'}`\n          this.#drop(session)\n          settle({ ok: false, ref, url: session.url, port: session.port, error })\n        }\n      })\n      startTimer = setTimeout(() => {\n        const error = `等待授权链接超时（${timeoutMs}ms）：${lastMeaningfulLine(session.output) ?? 'arkcli 没有输出授权链接'}`\n        this.#dispose(session)\n        settle({ ok: false, ref, url: session.url, port: session.port, error })\n      }, timeoutMs)\n    })\n  }\n\n  /**\n   * 查一次会话状态。\n   *\n   * @returns `{ok, state, url, code, error}`；ref 不存在时 state='unknown'。\n   */\n  poll(options = {}) {\n    const session = this.sessions.get(options.ref)\n    if (session === undefined) {\n      return { ok: false, state: 'unknown', url: undefined, code: undefined, error: '登录会话不存在（可能已取消、已过期或已完成）。' }\n    }\n    return { ok: true, state: session.state, url: session.url, code: session.code, error: session.error }\n  }\n\n  /** 等会话进入终态；已经终态则立刻返回。 */\n  #waitForTerminal(session, waitMs) {\n    if (session.state !== 'pending') return Promise.resolve({ state: session.state, error: session.error })\n    return new Promise((resolve) => {\n      let timer\n      const done = () => {\n        clearTimeout(timer)\n        session.waiters = session.waiters.filter((waiter) => waiter !== done)\n        resolve({ state: session.state, error: session.error })\n      }\n      session.waiters.push(done)\n      timer = setTimeout(done, waitMs)\n    })\n  }\n\n  /**\n   * 提交用户从浏览器地址栏复制的回调 URL（或裸授权码）。\n   *\n   * @param options - `ref`、`input`、转发后等终态的 `waitMs`。\n   * @returns `{ok, state, error}`（可能带 `note`）。\n   */\n  async submit(options = {}) {\n    const { ref, input, waitMs = LOGIN_WAIT_TIMEOUT_MS } = options\n    const session = this.sessions.get(ref)\n    if (session === undefined) return { ok: false, state: 'unknown', error: '登录会话不存在（可能已取消、已过期或已完成）。' }\n    if (session.state !== 'pending') return { ok: session.state === 'done', state: session.state, error: session.error }\n    const value = typeof input === 'string' ? input.trim() : ''\n    if (value === '') return { ok: false, state: 'pending', error: '没有拿到回调 URL：请把浏览器地址栏里的完整地址复制过来。' }\n    if (/^https?:\\/\\//i.test(value)) return await this.#forward(session, value, waitMs)\n    return await this.#codePath(session, value)\n  }\n\n  /** 把回调 URL 转发到本机回环监听。 */\n  async #forward(session, input, waitMs) {\n    let parsed\n    try {\n      parsed = new URL(input)\n    } catch {\n      return { ok: false, state: session.state, error: '粘贴的内容不是合法的 URL。' }\n    }\n    const pathname = parsed.pathname === '' ? '/' : parsed.pathname\n    if (pathname !== CALLBACK_PATH) {\n      // 只认这一个路由。以前是\"不是预期路由也照转，只是记一笔\" —— 那等于把本机回环\n      // 监听当成一个可以投递任意路径的转发器；而这条地址本来就是用户从浏览器地址栏\n      // 粘回来的回调 URL，正常必然是 CALLBACK_PATH。\n      return {\n        ok: false,\n        state: session.state,\n        error: `粘贴的地址路径是 ${pathname}，不是登录回调地址 ${CALLBACK_PATH}。请在浏览器地址栏里复制完整的那条地址。`,\n      }\n    }\n    const search = parsed.search\n    // 端口一律取会话里记录的那个：用户粘的 URL 可能来自上一次登录（端口已失效）。\n    const target = `http://127.0.0.1:${session.port}${pathname}${search}`\n    // Host 头是实测出来的，而且很挑：回环监听**只认** `127.0.0.1:<这个端口>`。\n    // 逐条试过（live listener，1.0.39）：\n    //   127.0.0.1:<port>  → 400 invalid callback parameters（Host 通过，只是参数假的）\n    //   localhost:<port>  → 400 invalid host\n    //   127.0.0.1 / localhost / [::1]:<port> / 端口差 1 / 大小写  → 400 invalid host\n    // 所以这里以 `127.0.0.1:<port>` 为准；万一以后哪个版本改成只认 localhost，\n    // 下面那个 `invalid host` 分支会自动再试一次，不至于把功能锁死在一个版本上。\n    const hosts = [`127.0.0.1:${session.port}`, `localhost:${session.port}`]\n    let status = 0\n    let body = ''\n    // 每次尝试只读一次正文（`createHttpFetch` 的返回值没有 `clone()`，别去二次读流）。\n    for (let attempt = 0; attempt < hosts.length; attempt += 1) {\n      let response\n      try {\n        response = await this.fetchImpl(target, { method: 'GET', headers: { host: hosts[attempt] }, redirect: 'manual' })\n      } catch (error) {\n        return { ok: false, state: session.state, error: `回调转发失败：${messageOf(error)}（本机监听可能已结束，请重新发起登录。）` }\n      }\n      status = Number(response.status)\n      try { body = await response.text() } catch { body = '' }\n      const retryable = status === 400 && /invalid host/i.test(body) && attempt + 1 < hosts.length\n      if (!retryable) break\n    }\n    if (!(status >= 200 && status < 300)) {\n      return { ok: false, state: session.state, error: `回调被拒绝（HTTP ${status}）：${body.slice(0, 200)}` }\n    }\n    const terminal = await this.#waitForTerminal(session, waitMs)\n    if (terminal.state === 'pending') return { ok: true, state: 'pending', error: undefined, note: session.note }\n    // 终态：捕获结果后立刻回收，绝不留一个还在跑的子进程。\n    const result = { ok: terminal.state === 'done', state: terminal.state, error: terminal.error, note: session.note }\n    this.#dispose(session)\n    return result\n  }\n\n  /** 裸授权码：本构建没有 `--code` 兑换，明确告诉调用方去粘 URL。 */\n  async #codePath(session, code) {\n    const result = await this.cli.run(['auth', 'login', '--no-browser', '--code', code], { home: session.home, timeoutMs: LOGIN_WAIT_TIMEOUT_MS })\n    if (result.ok) {\n      session.state = 'done'\n      session.code = 0\n      this.#dispose(session)\n      return { ok: true, state: 'done', error: undefined }\n    }\n    // 子进程保持存活：用户改成粘回调 URL 后这条会话仍然可用。\n    const detail = result.error ?? '未知错误'\n    return {\n      ok: false,\n      state: 'error',\n      error: `这个 arkcli 构建不支持 --code 授权码兑换（${detail}）。请在浏览器地址栏里复制完整的回调 URL（形如 http://127.0.0.1:<port>${CALLBACK_PATH}?...）再提交，不要只给授权码。`,\n    }\n  }\n\n  /** 取消一条会话：杀子进程并移出表。 */\n  cancel(options = {}) {\n    const session = this.sessions.get(options.ref)\n    if (session === undefined) return { ok: false, error: '登录会话不存在。' }\n    // 已经自己退出的会话没什么可杀的；如实回报，别让调用方以为\"取消\"生效了。\n    const killed = session.exited !== true\n    this.#dispose(session)\n    return { ok: true, killed }\n  }\n\n  /** 插件卸载/关闭时调用：杀掉所有子进程。 */\n  disposeAll() {\n    let killed = 0\n    for (const session of [...this.sessions.values()]) {\n      this.#dispose(session)\n      killed += 1\n    }\n    this.sessions.clear()\n    return { ok: true, killed }\n  }\n}\n"
