      "path": "usage.js",
      "content": "/**\n * 用量：**备选**的套餐额度来源（一对 AK/SK + Volcengine V4 签名）。\n *\n * 主路径是 arkcli（SSO 登录的账户自带 `usage plan`），这个模块是\"有 AK/SK、\n * 但不想装 arkcli / 不想 SSO 登录\"时的第二条路。\n *\n * ## 为什么不能只靠 `ark-` 订阅 key\n *\n * 火山方舟 Coding Plan 的 5 小时 / 每周 / 每月窗口**只存在于控制面**：\n * `GetCodingPlanUsage`（Service=ark，Version=2024-01-01）要求 Volcengine V4\n * HMAC-SHA256 签名，也就是一对 **AK/SK**。只用 `ark-...` 这个订阅 key 是查不到的\n * —— 2026-10-16 已实测：`/api/coding/v3` 下 usage/quota/subscription/limits/plan/\n * balance/account/me/billing 全部 404，聊天响应里也没有任何 `x-ratelimit-*` 头。\n *\n * 窗口的**重置时间**由控制面自己给（`ResetTimestamp`，秒），插件不推算：\n * 实测这个账号的 monthly 重置在 **15 日 23:59:59（UTC+8）**，不是自然月 1 号 ——\n * 那是套餐的订阅周期，不是日历月。所以页面只如实显示服务端给的那一刻。\n *\n * @module dsh-ark-coding-provider/usage\n */\n\nimport { createHash, createHmac } from 'node:crypto'\n\n/** 查询 Coding Plan 额度的控制面动作。 */\nexport const CODING_PLAN_USAGE_ACTION = 'GetCodingPlanUsage'\nexport const CODING_PLAN_USAGE_VERSION = '2024-01-01'\n/** 控制面主机与签名参数。 */\nexport const VOLC_HOST = 'open.volcengineapi.com'\nexport const VOLC_SERVICE = 'ark'\nexport const VOLC_DEFAULT_REGION = 'cn-beijing'\n\n// ---------------------------------------------------------------------------\n// Volcengine V4 签名\n// ---------------------------------------------------------------------------\n\n/** sha256 的十六进制摘要。 */\nexport function sha256Hex(input) {\n  return createHash('sha256').update(input).digest('hex')\n}\n\n/** HMAC-SHA256。 */\nexport function hmacSha256(key, data) {\n  return createHmac('sha256', key).update(data).digest()\n}\n\n/** `YYYYMMDDTHHMMSSZ`，签名要求的紧凑 ISO8601（UTC）。 */\nexport function amzDate(date) {\n  return date.toISOString().replace(/[:-]|\\.\\d{3}/g, '')\n}\n\n/**\n * 构造一次 Volcengine V4 签名的请求头。\n *\n * 与 AWS SigV4 同构（Volcengine 沿用了这套）：\n * 签名头固定为 `content-type;host;x-content-sha256;x-date`，\n * credential scope 为 `<date>/<region>/<service>/request`。\n *\n * @param options - 方法、路径、查询串、正文、AK/SK、区域与时间。\n * @returns 可直接合并进 fetch 的请求头。\n */\nexport function volcengineSignedHeaders(options) {\n  const {\n    accessKeyId,\n    secretAccessKey,\n    region = VOLC_DEFAULT_REGION,\n    service = VOLC_SERVICE,\n    host = VOLC_HOST,\n    method = 'POST',\n    path = '/',\n    query = '',\n    body = '',\n    contentType = 'application/json',\n    date = new Date(),\n  } = options\n\n  const xDate = amzDate(date)\n  const shortDate = xDate.slice(0, 8)\n  const payloadHash = sha256Hex(body)\n\n  const headers = {\n    'content-type': contentType,\n    host,\n    'x-content-sha256': payloadHash,\n    'x-date': xDate,\n  }\n  const signedHeaderNames = Object.keys(headers).sort()\n  const canonicalHeaders = signedHeaderNames.map((name) => `${name}:${headers[name]}`).join('\\n')\n  const signedHeaders = signedHeaderNames.join(';')\n\n  // 查询串必须按键名字典序排序后再拼接。\n  const canonicalQuery = query === ''\n    ? ''\n    : query\n      .split('&')\n      .filter((part) => part !== '')\n      .map((part) => {\n        const index = part.indexOf('=')\n        return index === -1 ? [part, ''] : [part.slice(0, index), part.slice(index + 1)]\n      })\n      .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))\n      .map(([key, value]) => `${key}=${value}`)\n      .join('&')\n\n  const canonicalRequest = [method, path, canonicalQuery, `${canonicalHeaders}\\n`, signedHeaders, payloadHash].join('\\n')\n  const credentialScope = `${shortDate}/${region}/${service}/request`\n  const stringToSign = ['HMAC-SHA256', xDate, credentialScope, sha256Hex(canonicalRequest)].join('\\n')\n\n  const kDate = hmacSha256(secretAccessKey, shortDate)\n  const kRegion = hmacSha256(kDate, region)\n  const kService = hmacSha256(kRegion, service)\n  const kSigning = hmacSha256(kService, 'request')\n  const signature = createHmac('sha256', kSigning).update(stringToSign).digest('hex')\n\n  return {\n    ...headers,\n    authorization: `HMAC-SHA256 Credential=${accessKeyId}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`,\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 套餐额度\n// ---------------------------------------------------------------------------\n\n/** 窗口级别 → 中文名。控制面返回的 Level 是 session/weekly/monthly。 */\nexport const WINDOW_LABELS = {\n  session: '5 小时',\n  fiveHour: '5 小时',\n  weekly: '每周',\n  monthly: '每月',\n  daily: '每日',\n}\n\n/**\n * 解析 `GetCodingPlanUsage` 的应答。\n *\n * 形状（社区实现一致）：`Result.QuotaUsage[] = { Level, Percent, ResetTimestamp }`，\n * `ResetTimestamp` 是**秒**。Coding Plan 只给百分比，没有绝对用量。\n *\n * @param payload - 已解析的 JSON 应答。\n * @returns 归一化的窗口列表，或抛错说明应答不可识别。\n */\n/** 时间戳是否落在能正常显示的范围里（秒或毫秒都算）。 */\nfunction inUsableRange(value) {\n  if (typeof value !== 'number' || !Number.isFinite(value)) return false\n  if (value <= 0) return false\n  const ms = value > 1e12 ? value : value * 1000\n  return ms <= 8.64e15\n}\n\nexport function parseCodingPlanUsage(payload) {\n  const result = payload?.Result ?? payload?.result\n  if (result === undefined || result === null || typeof result !== 'object') {\n    throw new Error('应答里没有 Result')\n  }\n  const rows = Array.isArray(result.QuotaUsage) ? result.QuotaUsage : Array.isArray(result.quotaUsage) ? result.quotaUsage : []\n  const windows = []\n  for (const row of rows) {\n    if (typeof row !== 'object' || row === null) continue\n    const level = typeof row.Level === 'string' ? row.Level : typeof row.level === 'string' ? row.level : undefined\n    const percentRaw = typeof row.Percent === 'number' ? row.Percent : typeof row.percent === 'number' ? row.percent : undefined\n    if (level === undefined || percentRaw === undefined) continue\n    const resetRaw = typeof row.ResetTimestamp === 'number' ? row.ResetTimestamp\n      : typeof row.resetTimestamp === 'number' ? row.resetTimestamp : undefined\n    windows.push({\n      level,\n      label: WINDOW_LABELS[level] ?? level,\n      percent: Math.max(0, Math.min(100, percentRaw)),\n      // 秒 → 毫秒；缺省时给 null，页面自行处理。\n      // 范围校验是必需的：负数会渲染成 1970-01-01，天文数字会渲染成 \"Invalid Date\"\n      // —— 用户看到的是假日期，比\"没有日期\"更糟（`formatClock` 的 try/catch 拦不住\n      // 这两种，它们根本不抛）。所以超出可用范围一律当\"没有\"。\n      resetAt: inUsableRange(resetRaw) ? (resetRaw > 1e12 ? resetRaw : resetRaw * 1000) : null,\n    })\n  }\n  const order = { session: 0, fiveHour: 0, daily: 1, weekly: 1, monthly: 2 }\n  windows.sort((left, right) => (order[left.level] ?? 9) - (order[right.level] ?? 9))\n  return {\n    windows,\n    status: typeof result.Status === 'string' ? result.Status : undefined,\n    updatedAt: typeof result.UpdateTimestamp === 'number' ? result.UpdateTimestamp : Date.now(),\n  }\n}\n\n/**\n * 查一次套餐额度。\n *\n * @param options - AK/SK、区域、超时与可选的 fetch。\n * @returns 归一化的额度；失败时抛错（调用方决定怎么降级）。\n */\nexport async function fetchCodingPlanUsage(options) {\n  const {\n    accessKeyId,\n    secretAccessKey,\n    region = VOLC_DEFAULT_REGION,\n    timeoutMs = 15_000,\n    fetchImpl = fetch,\n    date = new Date(),\n  } = options\n  if (typeof accessKeyId !== 'string' || accessKeyId.trim() === '') throw new Error('缺少 AccessKey ID')\n  if (typeof secretAccessKey !== 'string' || secretAccessKey.trim() === '') throw new Error('缺少 Secret AccessKey')\n\n  const query = `Action=${CODING_PLAN_USAGE_ACTION}&Version=${CODING_PLAN_USAGE_VERSION}`\n  const headers = volcengineSignedHeaders({\n    accessKeyId: accessKeyId.trim(),\n    secretAccessKey: secretAccessKey.trim(),\n    region,\n    query,\n    body: '',\n    date,\n  })\n\n  const controller = new AbortController()\n  const timer = setTimeout(() => controller.abort(new Error('usage timeout')), timeoutMs)\n  let response\n  try {\n    response = await fetchImpl(`https://${VOLC_HOST}/?${query}`, {\n      method: 'POST',\n      headers: { ...headers, accept: 'application/json', 'user-agent': 'dsh-ark-coding-provider' },\n      body: '',\n      signal: controller.signal,\n    })\n  } finally {\n    clearTimeout(timer)\n  }\n  const text = await response.text()\n  let payload\n  try {\n    payload = JSON.parse(text)\n  } catch {\n    throw new Error(`控制面返回了非 JSON 应答（HTTP ${response.status}）`)\n  }\n  // Volcengine 的错误有两种外壳：`ResponseMetadata.Error` 与顶层 `Error`。\n  const error = payload?.ResponseMetadata?.Error ?? payload?.Result?.Error ?? payload?.Error\n  if (error !== undefined && error !== null) {\n    const code = typeof error.Code === 'string' ? error.Code : ''\n    const message = typeof error.Message === 'string' ? error.Message : ''\n    if (code === 'NotLogin' || code === 'InvalidAccessKeyId' || code === 'SignatureDoesNotMatch' || /signature|access key/i.test(`${code} ${message}`)) {\n      throw new Error(`AK/SK 被拒绝（${code || 'auth'}）：请确认这对 AccessKey 属于同一个火山账号，并且有 ark 的读权限。`)\n    }\n    throw new Error(`${code || '控制面错误'}：${message}`)\n  }\n  if (!response.ok) throw new Error(`控制面 HTTP ${response.status}`)\n  return parseCodingPlanUsage(payload)\n}\n"
    },
    {
      "path": "models.js",
      "content": "/**\n * 火山方舟（Volcengine Ark）Coding Plan 模型目录。\n *\n * 每一行的容量、模态与思考档位都来自实测（2026-10-15，对本机 key 直接调用\n * `https://ark.cn-beijing.volces.com/api/coding/v3/chat/completions`）与官方文档\n * （https://docs.volcengine.com/docs/ark/coding-plan-personal-plan-overview）的交叉验证；\n * 无法确认的字段一律取保守值并在 `note` 里写明，绝不猜测。\n *\n * 字段说明：\n * - `contextWindow`：上下文窗口（tokens）。Ark 别名模型与带日期的目录 id 共用同一容量。\n * - `maxOutput`：单次请求 `max_tokens` 的上限。实测方式是在阶梯值上探测服务端是否拒绝。\n * - `input`：DSH 只认识 `text` / `image` 两种模态。模型若支持视频/音频输入，这里只体现\n *   它同时接受图片；DSH 的模态声明必须保守，宁可不给也不能错给。\n * - `efforts`：实测被服务端接受的 `reasoning_effort` 取值。`off` 映射为 `none`。\n * - `visionNote`：图片能力的实测结论，方便排查。\n *\n * 实测要点（非猜测）：\n * - `glm-5.3` 明确拒绝图片（`Model only support text input`），且不支持关闭思考\n *   （`thinking.type disabled is not supported`），也不接受 `reasoning_effort: none/minimal`。\n * - `deepseek-v4-pro` 收图后回答\"看不到图片\"，判定为纯文本；`deepseek-v4-flash` 每次带图\n *   都在 3 分钟内无响应，同样按纯文本处理（宁可少给不可错给）。\n * - `minimax-m3` 第 1 轮工具调用正常，但它回传的 `tool_calls[].type` 是 `functionfunction`\n *   （服务端序列化缺陷）。适配器重建请求时强制写 `type: \"function\"`，多轮工具调用因此可用。\n */\n\n/** 思考档位 id 到 wire 取值的映射。DSH 的 ReasoningEffortId 是不透明字符串。 */\nexport const EFFORT_WIRE = {\n  off: 'none',\n  minimal: 'minimal',\n  low: 'low',\n  medium: 'medium',\n  high: 'high',\n  max: 'max',\n}\n\n/** 档位显示名（中文环境与英文环境共用 id，展示交给语言包）。 */\nconst ALL_EFFORTS = [\n  { id: 'off', name: 'off' },\n  { id: 'minimal', name: 'minimal' },\n  { id: 'low', name: 'low' },\n  { id: 'medium', name: 'medium' },\n  { id: 'high', name: 'high' },\n  { id: 'max', name: 'max' },\n]\nconst NO_OFF = ALL_EFFORTS.filter((e) => e.id !== 'off')\n\n/**\n * 十二个 Coding Plan 模型。顺序 = 设置页与模型选择器的展示顺序：\n * 先把方舟自家 doubao 排在前面，再按第三方厂商分组。\n */\nexport const MODELS = [\n  {\n    id: 'doubao-seed-evolving',\n    name: 'Doubao-Seed-Evolving',\n    family: 'Doubao',\n    contextWindow: 1048576,\n    maxOutput: 262144,\n    input: ['text', 'image'],\n    efforts: ALL_EFFORTS,\n    defaultEffort: 'medium',\n    visionNote: '实测四象限配色全部答对',\n  },\n  {\n    id: 'doubao-seed-2.1-pro',\n    name: 'Doubao-Seed-2.1-pro',\n    family: 'Doubao',\n    contextWindow: 1048576,\n    maxOutput: 262144,\n    input: ['text', 'image'],\n    efforts: ALL_EFFORTS,\n    defaultEffort: 'medium',\n    visionNote: '实测四象限配色全部答对',\n  },\n  {\n    id: 'doubao-seed-2.1-lite',\n    name: 'Doubao-Seed-2.1-lite',\n    family: 'Doubao',\n    contextWindow: 1048576,\n    maxOutput: 262144,\n    input: ['text', 'image'],\n    efforts: ALL_EFFORTS,\n    defaultEffort: 'medium',\n    visionNote: '实测四象限配色全部答对',\n  },\n  {\n    id: 'doubao-seed-2.0-mini',\n    name: 'Doubao-Seed-2.0-mini',\n    family: 'Doubao',\n    contextWindow: 262144,\n    maxOutput: 131072,\n    input: ['text', 'image'],\n    efforts: ALL_EFFORTS,\n    defaultEffort: 'medium',\n    visionNote: '实测四象限配色全部答对',\n  },\n  {\n    id: 'minimax-m3',\n    name: 'MiniMax-M3',\n    family: 'MiniMax',\n    contextWindow: 1048576,\n    maxOutput: 131072,\n    input: ['text', 'image'],\n    efforts: ALL_EFFORTS,\n    defaultEffort: 'medium',\n    visionNote: '实测四象限配色全部答对；多轮工具调用需纠正 type 字段',\n  },\n  {\n    id: 'glm-5.3',\n    name: 'GLM-5.3',\n    family: 'Zhipu',\n    contextWindow: 1048576,\n    maxOutput: 131072,\n    input: ['text'],\n    // 实测：thinking 无法关闭，`none`/`minimal` 被拒绝；接受 low/medium/high/max\n    // （下面去掉 minimal 之后剩下的正好是这四档）。\n    efforts: NO_OFF.filter((e) => e.id !== 'minimal'),\n    defaultEffort: 'high',\n    visionNote: '纯文本：明确回 \"Model only support text input\"',\n  },\n  {\n    id: 'glm-5.3-flash',\n    name: 'GLM-5.3-Flash',\n    family: 'Zhipu',\n    contextWindow: 1048576,\n    maxOutput: 131072,\n    input: ['text', 'image'],\n    efforts: ALL_EFFORTS,\n    defaultEffort: 'high',\n    visionNote: '实测四象限配色全部答对（与 Ark /models 的 text-only 记录相反）',\n  },\n  {\n    id: 'deepseek-v4.1-flash',\n    name: 'DeepSeek-V4.1-Flash',\n    family: 'DeepSeek',\n    contextWindow: 1048576,\n    maxOutput: 393216,\n    input: ['text', 'image'],\n    efforts: ALL_EFFORTS,\n    defaultEffort: 'medium',\n    visionNote: '实测四象限配色全部答对（官方 deepseek-flash 支持视觉）',\n  },\n  {\n    id: 'deepseek-v4-flash',\n    name: 'DeepSeek-V4-Flash',\n    family: 'DeepSeek',\n    contextWindow: 1048576,\n    maxOutput: 393216,\n    input: ['text'],\n    efforts: ALL_EFFORTS,\n    defaultEffort: 'medium',\n    visionNote: '纯文本：带图请求三次均在 180s 内无响应，保守按不支持处理',\n  },\n  {\n    id: 'deepseek-v4-pro',\n    name: 'DeepSeek-V4-Pro',\n    family: 'DeepSeek',\n    contextWindow: 1048576,\n    maxOutput: 393216,\n    input: ['text'],\n    efforts: ALL_EFFORTS,\n    defaultEffort: 'medium',\n    visionNote: '纯文本：收图后回答\"看不到图片\"',\n  },\n  {\n    id: 'kimi-k2.8-preview',\n    name: 'Kimi-K2.8-Preview',\n    family: 'Moonshot',\n    contextWindow: 1048576,\n    maxOutput: 131072,\n    input: ['text', 'image'],\n    efforts: ALL_EFFORTS,\n    defaultEffort: 'medium',\n    visionNote: '实测四象限配色全部答对',\n  },\n  {\n    id: 'kimi-k3',\n    name: 'Kimi-K3',\n    family: 'Moonshot',\n    contextWindow: 1048576,\n    maxOutput: 131072,\n    input: ['text', 'image'],\n    efforts: ALL_EFFORTS,\n    defaultEffort: 'medium',\n    visionNote: '实测四象限配色全部答对',\n  },\n]\n\n/** 按 id 取一条目录记录。 */\nexport function modelById(id) {\n  return MODELS.find((m) => m.id === id)\n}\n\n// ---------------------------------------------------------------------------\n// 官方目录（arkcli `models search`）对照\n// ---------------------------------------------------------------------------\n\n/**\n * 为什么官方目录**只做对照、不做覆盖**。\n *\n * 上面的 12 行容量与模态是**直接打 Coding Plan 端点实测**出来的；而 arkcli\n * `models search` 返回的是方舟**通用目录**的元数据。两者不是同一份事实源：\n * 已知的真实分歧就有一个 —— 通用目录把 `glm-5.3-flash` 记成纯文本，而实测\n * 它收图并答对了四象限配色。拿通用目录去覆盖实测值，等于用较不可靠的来源\n * 推翻较可靠的来源。\n *\n * 所以这里把官方值挂在 `official` 上并列出 `conflicts`，由设置页并排展示。\n * 好处是：官方目录一旦更新（新增模型、改容量），用户马上能在界面上看到差异，\n * 而不是被插件里写死的快照蒙在鼓里。\n */\n\n/** 把 id / 显示名归一成可比较的键：小写、非字母数字折叠成单个 `-`。 */\nexport function catalogKeyOf(text) {\n  if (typeof text !== 'string') return ''\n  return text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')\n}\n\n/** 把官方目录索引成 `键 → 条目`，同时按 id 与显示名建索引。 */\nexport function indexCatalog(items) {\n  const map = new Map()\n  if (!Array.isArray(items)) return map\n  for (const item of items) {\n    if (typeof item !== 'object' || item === null) continue\n    const id = typeof item.id === 'string' ? item.id : (typeof item.name === 'string' ? item.name : '')\n    if (id === '') continue\n    for (const key of new Set([catalogKeyOf(id), catalogKeyOf(item.displayName)])) {\n      if (key !== '' && !map.has(key)) map.set(key, item)\n    }\n  }\n  return map\n}\n\n/** 官方条目里我们关心的那部分事实。 */\nfunction officialOf(item) {\n  if (item === undefined) return undefined\n  const modalities = Array.isArray(item.inputModalities)\n    ? item.inputModalities.filter((m) => m === 'text' || m === 'image')\n    : []\n  const thinking = item.capabilities !== undefined && item.capabilities !== null\n    ? item.capabilities.thinking\n    : undefined\n  return {\n    id: typeof item.id === 'string' ? item.id : '',\n    displayName: typeof item.displayName === 'string' ? item.displayName : '',\n    version: typeof item.version === 'string' ? item.version : '',\n    contextWindow: Number.isFinite(item.contextWindow) ? item.contextWindow : undefined,\n    maxInputTokens: Number.isFinite(item.maxInputTokens) ? item.maxInputTokens : undefined,\n    maxOutputTokens: Number.isFinite(item.maxOutputTokens) ? item.maxOutputTokens : undefined,\n    inputModalities: modalities,\n    thinking: typeof thinking === 'boolean' ? thinking : undefined,\n    lifecycleStatus: typeof item.lifecycleStatus === 'string' ? item.lifecycleStatus : '',\n  }\n}\n\n/**\n * 把官方目录对照到内置模型上。\n *\n * 返回新的模型数组（不修改入参），每条可能多出：\n * - `official`：官方目录里对应条目的元数据，没匹配上就是 `undefined`。\n * - `conflicts`：官方值与实测值**不一致的字段名**列表（`contextWindow` /\n *   `maxOutput` / `input`）。空数组表示一致或无从比较。\n *\n * 另外回报 `unmatchedOfficial`：官方目录里存在、但不在这 12 行里的模型数 ——\n * 这是\"官方又发新模型了\"的信号，设置页据此提示用户。\n */\nexport function annotateMode